    { const char * tb_v2230 = "// ядро процессора («звезда»): его номер, кого он сейчас ведёт, свой стек для пустого хода.\n"; *(const char * *)tb_grow(v_lines) = tb_v2230; }
    { const char * tb_v2231 = "// Регистр GS у каждого ядра смотрит на его запись (в самом начале — адрес её самой)\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "#define TB_NCPU 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
    { const char * tb_v2233 = "typedef struct tb_cpu_s {\n"; *(const char * *)tb_grow(v_lines) = tb_v2233; }
