    { const char * tb_v2242 = "TB_API int tb_ncpu = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2242; }
    { const char * tb_v2243 = "TB_INL tb_cpu *tb_me(void) { tb_cpu *c; __asm__ volatile(\"movq %%gs:0, %0\" : \"=r\"(c)); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2243; }
    { const char * tb_v2244 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v2244; }
    { const char * tb_v2245 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v2245; }
    { const char * tb_v2246 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2246; }
    { const char * tb_v2247 = "TB_INL uint64_t tb_irq_save(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2247; }
    { const char * tb_v2248 = "    uint64_t f;\n"; *(const char * *)tb_grow(v_lines) = tb_v2248; }
    { const char * tb_v2249 = "    __asm__ volatile(\"pushfq\\npopq %0\\ncli\" : \"=r\"(f) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2249; }
