    { const char * tb_v2258 = "    __asm__ volatile(\"pushq %0\\npopfq\" : : \"r\"(f) : \"memory\", \"cc\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2258; }
    { const char * tb_v2259 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2259; }
