    { const char * tb_v2719 = "    if (b == 0) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2719; }
    { const char * tb_v2720 = "    if (a == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2720; }
    { const char * tb_v2721 = "    if (b == (double)(long long)b && b > -64 && b < 64) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2721; }
    { const char * tb_v2722 = "        double r = 1, m = a; long long n = (long long)(b < 0 ? -b : b);\n"; *(const char * *)tb_grow(v_lines) = tb_v2722; }
    { const char * tb_v2723 = "        while (n) { if (n & 1) r *= m; m *= m; n >>= 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2723; }
    { const char * tb_v2724 = "        return b < 0 ? 1 / r : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2724; }
    { const char * tb_v2725 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2725; }
    { const char * tb_v2726 = "    if (a < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2726; }
    { const char * tb_v2727 = "    return exp(b * log(a));\n"; *(const char * *)tb_grow(v_lines) = tb_v2727; }
    { const char * tb_v2728 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2728; }
    { const char * tb_v2729 = "TB_API float powf(float a, float b) { return (float)pow(a, b); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2729; }
    { const char * tb_v2730 = "TB_API void *bsearch(const void *key, const void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2730; }
    { const char * tb_v2731 = "    size_t lo = 0, hi = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2731; }
    { const char * tb_v2732 = "    while (lo < hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2732; }
    { const char * tb_v2733 = "        size_t mid = (lo + hi) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2733; }
    { const char * tb_v2734 = "        const unsigned char *p = (const unsigned char *)base + mid * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
    { const char * tb_v2735 = "        int c = cmp(key, p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2735; }
    { const char * tb_v2736 = "        if (c == 0) return (void *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2736; }
    { const char * tb_v2737 = "        if (c < 0) hi = mid; else lo = mid + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2737; }
    { const char * tb_v2738 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2738; }
    { const char * tb_v2739 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2739; }
    { const char * tb_v2740 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2740; }
