    { const char * tb_v2743 = "// ---------- ядро: прерывания, таймер, клавиатура, задачи, страницы памяти ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2743; }
    { const char * tb_v2744 = "// on all cores здесь выполняется на одном ядре по очереди (как и было),\n"; *(const char * *)tb_grow(v_lines) = tb_v2744; }
    { const char * tb_v2745 = "// а background — настоящая задача: таймер переключает задачи каждые 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v2745; }
    { const char * tb_v2746 = "TB_API long sysconf(int n) { (void)n; return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2746; }
