    { const char * tb_v2749 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2749; }
    { const char * tb_v2750 = "// адреса из раскладки ядра (компоновщик): где код, где кончается нижняя память, где куча\n"; *(const char * *)tb_grow(v_lines) = tb_v2750; }
