    { const char * tb_v2759 = "    snprintf(buf, sizeof buf, \"\\n*** ядро остановлено: %s (0x%llx, 0x%llx)\\n\", what, (unsigned long long)a, (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v2759; }
