    { const char * tb_v2774 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2774; }
    { const char * tb_v2775 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v2775; }
    { const char * tb_v2776 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v2776; }
    { const char * tb_v2777 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v2777; }
    { const char * tb_v2778 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v2778; }
    { const char * tb_v2779 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v2779; }
    { const char * tb_v2780 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2780; }
    { const char * tb_v2781 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2781; }
    { const char * tb_v2782 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2782; }
    { const char * tb_v2783 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2783; }
    { const char * tb_v2784 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2784; }
    { const char * tb_v2785 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2785; }
    { const char * tb_v2786 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2786; }
    { const char * tb_v2787 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2787; }
    { const char * tb_v2788 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2788; }
    { const char * tb_v2789 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v2789; }
    { const char * tb_v2790 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2790; }
    { const char * tb_v2791 = "#define TB_F_VEC 79\n"; *(const char * *)tb_grow(v_lines) = tb_v2791; }
    { const char * tb_v2792 = "#define TB_F_ERR 80\n"; *(const char * *)tb_grow(v_lines) = tb_v2792; }
