    { const char * tb_v2805 = "    int no;                               // номер клетки: по порядку запуска (1, 2, 3 ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v2805; }
    { const char * tb_v2806 = "    uint64_t gen; long long mem;          // поколение слота (для хозяина кусков) и байты клетки\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
