    { const char * tb_v2808 = "    int svc;                              // служба (a = service f()): ей можно в запас памяти\n"; *(const char * *)tb_grow(v_lines) = tb_v2808; }
    { const char * tb_v2809 = "    int soft;                             // сейчас new_mem / grow_mem: нет памяти — ошибка, а не падение\n"; *(const char * *)tb_grow(v_lines) = tb_v2809; }
    { const char * tb_v2810 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
