    { const char * tb_v2819 = "TB_API volatile uint64_t tb_ms = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2819; }
    { const char * tb_v2820 = "TB_API void (*tb_irq_fn[16])(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2820; }
