    { const char * tb_v2822 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2822; }
    { const char * tb_v2823 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
    { const char * tb_v2826 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v2826; }
    { const char * tb_v2827 = "    memcpy(b, tb_tls_start, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2827; }
    { const char * tb_v2828 = "    unsigned char *tp = b + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2828; }
