    { const char * tb_v2830 = "    return tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2830; }
    { const char * tb_v2831 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2831; }
    { const char * tb_v2832 = "TB_API void tb_set_fs(unsigned char *tp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2832; }
    { const char * tb_v2833 = "    uint64_t v = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2833; }
    { const char * tb_v2834 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000100u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2834; }
    { const char * tb_v2835 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2835; }
