    { const char * tb_v2837 = "TB_INL void *tb_tls_self(void) { void *p; __asm__ volatile(\"movq %%fs:0, %0\" : \"=r\"(p)); return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2837; }
    { const char * tb_v2838 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v2838; }
    { const char * tb_v2839 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2839; }
    { const char * tb_v2840 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v2840; }
    { const char * tb_v2841 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v2841; }
    { const char * tb_v2842 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2842; }
