    { const char * tb_v2846 = "// new_mem / grow_mem просят память «мягко»: не хватило — ответ else err, клетка живёт\n"; *(const char * *)tb_grow(v_lines) = tb_v2846; }
    { const char * tb_v2847 = "TB_API int tb_mem_soft_now(void) { return !tb_in_irq && tb_slots[tb_cur].soft > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2847; }
