    { const char * tb_v3000 = "    if (ch == 0 || (unsigned char)(tb_khead + 1) == tb_ktail) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3000; }
    { const char * tb_v3001 = "    tb_kq[tb_khead] = ch;\n"; *(const char * *)tb_grow(v_lines) = tb_v3001; }
