    { const char * tb_v3004 = "TB_API void tb_key_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3004; }
    { const char * tb_v3005 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v3005; }
