    { const char * tb_v3008 = "    if (st & 0x20) return;   // байт мыши (его ждёт прерывание 12)\n"; *(const char * *)tb_grow(v_lines) = tb_v3008; }
    { const char * tb_v3009 = "    tb_key_byte(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v3009; }
