    { const char * tb_v3019 = "// --- страницы памяти (4 уровня): нижняя память — страницы по 4 КБ (адрес 0 и код защищены,\n"; *(const char * *)tb_grow(v_lines) = tb_v3019; }
    { const char * tb_v3020 = "// у стеков — пустая страница-сторож), выше — большие по 2 МБ (куча и свободная память) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3020; }
    { const char * tb_v3021 = "#define TB_LOW_PTS 32                                 // 32 таблицы × 2 МБ = нижние 64 МБ\n"; *(const char * *)tb_grow(v_lines) = tb_v3021; }
