    { const char * tb_v3027 = "TB_API uint64_t tb_ram_end = 0, tb_pg_next = 0, tb_pg_free = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3027; }
    { const char * tb_v3028 = "// таблицы на время загрузки: первые 4 ГБ большими страницами (их строит _start ещё в 32 битах)\n"; *(const char * *)tb_grow(v_lines) = tb_v3028; }
