    { const char * tb_v3032 = "TB_API uint32_t tb_boot_magic __attribute__((used)), tb_boot_mbi __attribute__((used));\n"; *(const char * *)tb_grow(v_lines) = tb_v3032; }
    { const char * tb_v3033 = "// ---- модули (файлы, которые загрузчик положил рядом с ядром: qemu -initrd \"a.oapp,b.oapp\") ----\n"; *(const char * *)tb_grow(v_lines) = tb_v3033; }
    { const char * tb_v3034 = "// у Multiboot: флаг 3 — есть модули; mbi[5] — сколько, mbi[6] — где список (по 16 байт: начало, конец, имя, 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3034; }
    { const char * tb_v3035 = "TB_API uint32_t *tb_mods(long long *n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "    uint32_t *mbi = (uint32_t *)(uintptr_t)tb_boot_mbi;\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
    { const char * tb_v3037 = "    *n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3037; }
    { const char * tb_v3038 = "    if (tb_boot_magic != 0x2BADB002u || mbi == 0 || !(mbi[0] & 8)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3038; }
    { const char * tb_v3039 = "    *n = mbi[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v3039; }
