    { const char * tb_v3043 = "    long long n; uint32_t *m = tb_mods(&n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3043; }
    { const char * tb_v3044 = "    uint64_t top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3044; }
    { const char * tb_v3045 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3045; }
    { const char * tb_v3046 = "        if (m[4 * i + 1] > top) top = m[4 * i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v3046; }
