    { const char * tb_v3055 = "TB_API long long tb_module_size(long long i) { long long n; uint32_t *m = tb_mods(&n); return i >= 0 && i < n ? (long long)m[4 * i + 1] - m[4 * i] : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3055; }
    { const char * tb_v3056 = "// таблица имён ядра (её заполняет компоновщик elf_link.py): по алфавиту, 16 байт на имя —\n"; *(const char * *)tb_grow(v_lines) = tb_v3056; }
    { const char * tb_v3057 = "// адрес, где имя (от начала таблицы), длина имени. Программы Омниума находят по ней функции ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v3057; }
    { const char * tb_v3058 = "TB_API volatile uint64_t tb_ksym_tab __attribute__((used)) = 1, tb_ksym_n __attribute__((used)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3058; }
    { const char * tb_v3059 = "TB_API long long tb_kernel_symbol(const char *nm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3059; }
    { const char * tb_v3060 = "    uint64_t t = tb_ksym_tab;\n"; *(const char * *)tb_grow(v_lines) = tb_v3060; }
    { const char * tb_v3061 = "    long long lo = 0, hi = (long long)tb_ksym_n - 1, len = (long long)strlen(nm);\n"; *(const char * *)tb_grow(v_lines) = tb_v3061; }
    { const char * tb_v3062 = "    if (t <= 1) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3062; }
    { const char * tb_v3063 = "    while (lo <= hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3063; }
    { const char * tb_v3064 = "        long long mid = (lo + hi) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v3064; }
    { const char * tb_v3065 = "        const uint64_t *e = (const uint64_t *)(uintptr_t)(t + 16 * mid);\n"; *(const char * *)tb_grow(v_lines) = tb_v3065; }
    { const char * tb_v3066 = "        uint32_t off = (uint32_t)e[1], n = (uint32_t)(e[1] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v3066; }
    { const char * tb_v3067 = "        int r = memcmp((const char *)(uintptr_t)(t + off), nm, (size_t)(n < len ? n : len));\n"; *(const char * *)tb_grow(v_lines) = tb_v3067; }
    { const char * tb_v3068 = "        if (r == 0) r = n < len ? -1 : n > len ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3068; }
    { const char * tb_v3069 = "        if (r == 0) return (long long)e[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v3069; }
    { const char * tb_v3070 = "        if (r < 0) lo = mid + 1; else hi = mid - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3070; }
    { const char * tb_v3071 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3071; }
