    { const char * tb_v3073 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3073; }
    { const char * tb_v3074 = "// позвать функцию по адресу (начало загруженной программы): без параметров, без ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3074; }
    { const char * tb_v3075 = "TB_API void tb_call_address(long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3075; }
    { const char * tb_v3076 = "    if (a == 0) tb_panic(\"call_address: адрес 0\", 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3076; }
    { const char * tb_v3077 = "    ((void (*)(void))(uintptr_t)a)();\n"; *(const char * *)tb_grow(v_lines) = tb_v3077; }
    { const char * tb_v3078 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3078; }
    { const char * tb_v3079 = "TB_API void tb_unmap(uint64_t a) { tb_pt[a >> 21][(a >> 12) & 511] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3079; }
    { const char * tb_v3080 = "TB_API int tb_is_guard(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3080; }
    { const char * tb_v3081 = "    if (a >= (uint64_t)(uintptr_t)tb_stack && a < (uint64_t)(uintptr_t)tb_stack + 4096) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3081; }
    { const char * tb_v3082 = "    for (int i = 1; i < TB_NTASK; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3082; }
    { const char * tb_v3083 = "        if (a >= (uint64_t)(uintptr_t)tb_tstacks[i] && a < (uint64_t)(uintptr_t)tb_tstacks[i] + 4096) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3083; }
    { const char * tb_v3084 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3084; }
    { const char * tb_v3085 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3085; }
    { const char * tb_v3086 = "TB_API void tb_paging_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3086; }
    { const char * tb_v3087 = "    uint64_t low = (uint64_t)(uintptr_t)tb_heap_area;\n"; *(const char * *)tb_grow(v_lines) = tb_v3087; }
    { const char * tb_v3088 = "    uint64_t cs = (uint64_t)(uintptr_t)tb_code_start, ce = (uint64_t)(uintptr_t)tb_code_end;\n"; *(const char * *)tb_grow(v_lines) = tb_v3088; }
    { const char * tb_v3089 = "    if (low > TB_LOW_PTS * 0x200000ull) tb_panic(\"ядро слишком большое для нижних страниц\", low, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3089; }
    { const char * tb_v3090 = "    if (tb_ram_end < (uint64_t)(uintptr_t)tb_kernel_end + 0x400000u) tb_panic(\"мало памяти: запусти qemu с -m 256\", tb_ram_end, (uint64_t)(uintptr_t)tb_kernel_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3090; }
    { const char * tb_v3091 = "    for (uint64_t a = 0; a < low; a += 4096) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3091; }
