    { const char * tb_v3094 = "        tb_pt[a >> 21][(a >> 12) & 511] = a | flags;\n"; *(const char * *)tb_grow(v_lines) = tb_v3094; }
    { const char * tb_v3095 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3095; }
    { const char * tb_v3096 = "    tb_unmap(0);                                              // адрес 0: «пустая ссылка»\n"; *(const char * *)tb_grow(v_lines) = tb_v3096; }
    { const char * tb_v3097 = "    tb_unmap((uint64_t)(uintptr_t)tb_stack);                  // сторож под стеком main\n"; *(const char * *)tb_grow(v_lines) = tb_v3097; }
    { const char * tb_v3098 = "    for (int i = 1; i < TB_NTASK; i++) tb_unmap((uint64_t)(uintptr_t)tb_tstacks[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3098; }
    { const char * tb_v3099 = "    tb_pml4[0] = (uint64_t)(uintptr_t)tb_pdpt | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3099; }
    { const char * tb_v3100 = "    uint64_t gbs = (tb_ram_end + (1ull << 30) - 1) >> 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v3100; }
    { const char * tb_v3101 = "    if (gbs > TB_MAX_GB) gbs = TB_MAX_GB;\n"; *(const char * *)tb_grow(v_lines) = tb_v3101; }
    { const char * tb_v3102 = "    if (gbs < 1) gbs = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3102; }
    { const char * tb_v3103 = "    for (uint64_t g = 0; g < gbs; g++) tb_pdpt[g] = (uint64_t)(uintptr_t)tb_pdir[g] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3103; }
    { const char * tb_v3104 = "    for (uint64_t t = 0; t < low >> 21; t++) tb_pdir[0][t] = (uint64_t)(uintptr_t)tb_pt[t] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3104; }
    { const char * tb_v3105 = "    for (uint64_t a = low; a < tb_ram_end; a += 0x200000ull) tb_pdir[a >> 30][(a >> 21) & 511] = a | 0x83;\n"; *(const char * *)tb_grow(v_lines) = tb_v3105; }
    { const char * tb_v3106 = "    // окна устройств PCI (AHCI, NVMe, APIC ...) — от 3 до 4 ГБ, без кэша; память там не трогаем\n"; *(const char * *)tb_grow(v_lines) = tb_v3106; }
    { const char * tb_v3107 = "    tb_pdpt[3] = (uint64_t)(uintptr_t)tb_pdir[3] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3107; }
    { const char * tb_v3108 = "    for (uint64_t a = 0xC0000000ull; a < 0x100000000ull; a += 0x200000ull)\n"; *(const char * *)tb_grow(v_lines) = tb_v3108; }
    { const char * tb_v3109 = "        if (a >= tb_ram_end) tb_pdir[3][(a >> 21) & 511] = a | 0x83 | 0x18;\n"; *(const char * *)tb_grow(v_lines) = tb_v3109; }
    { const char * tb_v3110 = "    // CR0.WP: и ядро не может писать в страницы «только читать»\n"; *(const char * *)tb_grow(v_lines) = tb_v3110; }
    { const char * tb_v3111 = "    __asm__ volatile(\"movq %0, %%cr3\\nmovq %%cr0, %%rax\\norq $0x10000, %%rax\\nmovq %%rax, %%cr0\\n\" : : \"r\"(tb_pml4) : \"rax\", \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3111; }
