    { const char * tb_v3116 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3116; }
    { const char * tb_v3117 = "TB_API long long tb_page_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3117; }
    { const char * tb_v3118 = "    uint64_t f = tb_irq_save(), p = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3118; }
