    { const char * tb_v3306 = "// --- несколько ядер процессора («звёзды») ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3306; }
    { const char * tb_v3307 = "// Какие ядра есть — из таблицы ACPI «APIC» (MADT). Каждое будим так: INIT, потом дважды\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
