    { const char * tb_v3311 = "// таблицы ACPI лежат выше памяти, которую назвал загрузчик: показываем их кусок 2 МБ (только читать)\n"; *(const char * *)tb_grow(v_lines) = tb_v3311; }
    { const char * tb_v3312 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3312; }
    { const char * tb_v3313 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3313; }
    { const char * tb_v3314 = "    uint64_t *e = &tb_pdir[a >> 30][(a >> 21) & 511];\n"; *(const char * *)tb_grow(v_lines) = tb_v3314; }
