    { const char * tb_v3319 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3319; }
    { const char * tb_v3320 = "TB_API int tb_find_cpus(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3320; }
    { const char * tb_v3321 = "    unsigned char *rsdp = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3321; }
    { const char * tb_v3322 = "    for (uint64_t a = 0xE0000; a < 0x100000 && !rsdp; a += 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v3322; }
    { const char * tb_v3323 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3323; }
    { const char * tb_v3324 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3324; }
    { const char * tb_v3325 = "    unsigned char *rsdt = (unsigned char *)(uintptr_t)*(uint32_t *)(rsdp + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3325; }
