    { const char * tb_v3344 = "TB_API volatile int tb_ap_up = 0, tb_ap_id = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "__asm__(\".text\\n.global tb_tramp\\n.global tb_tramp_end\\n.global tb_tr_cr3\\n.global tb_tr_stack\\n.code16\\ntb_tramp:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
    { const char * tb_v3346 = "        \"  cli\\n  xorw %ax, %ax\\n  movw %ax, %ds\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3346; }
