    { const char * tb_v3349 = "        \"  ljmpl $0x08, $(0x8000 + (tb_tr32 - tb_tramp))\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3349; }
    { const char * tb_v3350 = "        \".code32\\ntb_tr32:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3350; }
    { const char * tb_v3351 = "        \"  movw $0x10, %ax\\n  movw %ax, %ds\\n  movw %ax, %ss\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3351; }
    { const char * tb_v3352 = "        \"  movl %cr4, %eax\\n  orl $0x620, %eax\\n  movl %eax, %cr4\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3352; }
