    { const char * tb_v3354 = "        \"  movl $0xC0000080, %ecx\\n  rdmsr\\n  orl $0x100, %eax\\n  wrmsr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3354; }
    { const char * tb_v3355 = "        \"  movl %cr0, %eax\\n  andl $0xFFFFFFFB, %eax\\n  orl $0x80010002, %eax\\n  movl %eax, %cr0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3355; }
    { const char * tb_v3356 = "        \"  ljmpl $0x18, $(0x8000 + (tb_tr64 - tb_tramp))\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3356; }
    { const char * tb_v3357 = "        \".code64\\ntb_tr64:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3357; }
    { const char * tb_v3358 = "        \"  movq 0x8000 + (tb_tr_stack - tb_tramp), %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3358; }
    { const char * tb_v3359 = "        \"  movabsq $tb_ap_main, %rax\\n  call *%rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3359; }
    { const char * tb_v3360 = "        \"1:\\n  cli\\n  hlt\\n  jmp 1b\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3360; }
