    { const char * tb_v3362 = "        \"tb_tr_gdtr:\\n  .word 31\\n  .long 0x8000 + (tb_tr_gdt - tb_tramp)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "        \".balign 8\\ntb_tr_cr3:\\n  .quad 0\\ntb_tr_stack:\\n  .quad 0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
    { const char * tb_v3364 = "        \"tb_tramp_end:\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3364; }
    { const char * tb_v3365 = "TB_API void tb_lapic_timer_start(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "    tb_lapic_w(0x3E0, 3);                              // делитель 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
