    { const char * tb_v3374 = "                     \"movw $0x10, %%ax\\nmovw %%ax, %%ds\\nmovw %%ax, %%es\\nmovw %%ax, %%fs\\nmovw %%ax, %%gs\\nmovw %%ax, %%ss\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3374; }
