    { const char * tb_v3379 = "// ядро процессора проснулось: свои сегменты, своя запись, таймер APIC — и в пустой ход\n"; *(const char * *)tb_grow(v_lines) = tb_v3379; }
    { const char * tb_v3380 = "__attribute__((used, noreturn)) TB_API void tb_ap_main(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3380; }
