    { const char * tb_v3589 = "// как в POSIX: файл на месте назначения заменяется (обычный rename на Windows так не умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "TB_API int tb_win_rename(const char *from, const char *to) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
    { const char * tb_v3591 = "    wchar_t *a = tb_wide(from), *b = tb_wide(to);\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
