    { const char * tb_v3609 = "// поэтому команда целиком берётся ещё в одни кавычки\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "TB_API wchar_t *tb_win_cmd(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "    size_t n = strlen(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
