    { const char * tb_v4640 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4640; }
    { const char * tb_v4641 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v4641; }
    { const char * tb_v4642 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v4642; }
    { const char * tb_v4643 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4643; }
    { const char * tb_v4644 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4644; }
    { const char * tb_v4645 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4645; }
    { const char * tb_v4646 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4646; }
    { const char * tb_v4647 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v4647; }
    { const char * tb_v4648 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v4648; }
    { const char * tb_v4649 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v4649; }
    { const char * tb_v4650 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v4650; }
    { const char * tb_v4651 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4651; }
    { const char * tb_v4652 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v4652; }
    { const char * tb_v4653 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v4653; }
    { const char * tb_v4654 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4654; }
    { const char * tb_v4655 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4655; }
    { const char * tb_v4656 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4656; }
    { const char * tb_v4657 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4657; }
    { const char * tb_v4658 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4658; }
    { const char * tb_v4659 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4659; }
    { const char * tb_v4660 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4660; }
    { const char * tb_v4661 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4661; }
    { const char * tb_v4662 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4662; }
    { const char * tb_v4663 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v4663; }
    { const char * tb_v4664 = "TB_API _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4664; }
    { const char * tb_v4665 = "TB_API _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4665; }
    { const char * tb_v4666 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v4666; }
    { const char * tb_v4667 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4667; }
    { const char * tb_v4668 = "TB_API void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4668; }
    { const char * tb_v4669 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v4669; }
