    { const char * tb_v4671 = "    long long lim = tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4671; }
    { const char * tb_v4672 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4672; }
    { const char * tb_v4673 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v4673; }
    { const char * tb_v4674 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v4674; }
    { const char * tb_v4675 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v4675; }
    { const char * tb_v4676 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4676; }
