    { const char * tb_v4679 = "        m = tb_lang_en_v == 1 ? \"the stack is full: a function calls itself too deep (endless recursion?)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4679; }
    { const char * tb_v4680 = "                              : \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4680; }
