    { const char * tb_v4904 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4904; }
    { const char * tb_v4905 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4905; }
    { const char * tb_v4906 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4906; }
    { const char * tb_v4907 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4907; }
