    { const char * tb_v4965 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v4965; }
    { const char * tb_v4966 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4966; }
    { const char * tb_v4967 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v4967; }
    { const char * tb_v4968 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4968; }
