    { const char * tb_v5568 = "    const unsigned char *p = (const unsigned char *)s, *e = p + nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
    { const char * tb_v5570 = "    while (p < e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5570; }
    { const char * tb_v5571 = "        if (*p < 0x80) { p++; n++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5571; }
