    { const char * tb_v5583 = "TB_INL void tb_u8c_clear(void) { for (int k = 0; k < 4; k++) tb_u8c[k].p = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5583; }
    { const char * tb_v5584 = "// nb < 0: длину в байтах посчитать (текст не меняется); nb >= 0: текст, в который дописывают\n"; *(const char * *)tb_grow(v_lines) = tb_v5584; }
    { const char * tb_v5585 = "TB_API tb_u8slot *tb_u8info(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5585; }
    { const char * tb_v5586 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5586; }
    { const char * tb_v5587 = "        tb_u8slot *c = &tb_u8c[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v5587; }
    { const char * tb_v5588 = "        if (c->p != s) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5588; }
    { const char * tb_v5589 = "        if (nb < 0 || nb == c->nb) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5589; }
    { const char * tb_v5590 = "        if (nb > c->nb) {   // дописали в конец: досчитать только новое\n"; *(const char * *)tb_grow(v_lines) = tb_v5590; }
    { const char * tb_v5591 = "            // последняя буква могла быть недописанной: пересчитать с её начала (не дальше 3 байт назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v5591; }
    { const char * tb_v5592 = "            long long from = c->nb, b = c->nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5592; }
    { const char * tb_v5593 = "            while (b > 0 && c->nb - b < 3 && ((unsigned char)s[b - 1] & 0xC0) == 0x80) b--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5593; }
    { const char * tb_v5594 = "            if (b > 0 && (unsigned char)s[b - 1] >= 0xC0) from = b - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5594; }
    { const char * tb_v5595 = "            c->nl = c->nl - tb_u8count(s + from, c->nb - from) + tb_u8count(s + from, nb - from);\n"; *(const char * *)tb_grow(v_lines) = tb_v5595; }
    { const char * tb_v5596 = "            c->nb = nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5596; }
    { const char * tb_v5597 = "            if (c->bi > from) { c->li = 0; c->bi = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5597; }
    { const char * tb_v5598 = "            return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5598; }
    { const char * tb_v5599 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5599; }
    { const char * tb_v5600 = "        break;\n"; *(const char * *)tb_grow(v_lines) = tb_v5600; }
    { const char * tb_v5601 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5601; }
    { const char * tb_v5602 = "    tb_u8slot *c = &tb_u8c[tb_u8c_next];\n"; *(const char * *)tb_grow(v_lines) = tb_v5602; }
    { const char * tb_v5603 = "    tb_u8c_next = (tb_u8c_next + 1) & 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v5603; }
    { const char * tb_v5604 = "    c->p = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5604; }
    { const char * tb_v5605 = "    c->nb = nb >= 0 ? nb : (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v5605; }
    { const char * tb_v5606 = "    c->nl = tb_u8count(s, c->nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5606; }
    { const char * tb_v5607 = "    c->li = 0; c->bi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5607; }
    { const char * tb_v5608 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5608; }
    { const char * tb_v5609 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5609; }
    { const char * tb_v5610 = "TB_API long long tb_ulen(const char *s) { return tb_u8info(s, -1)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5610; }
    { const char * tb_v5611 = "TB_API long long tb_ulen_n(const char *s, long long nb) { return nb < 0 ? tb_ulen(s) : tb_u8info(s, nb)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5611; }
    { const char * tb_v5612 = "// байт, с которого начинается буква i (i == букв — конец текста)\n"; *(const char * *)tb_grow(v_lines) = tb_v5612; }
    { const char * tb_v5613 = "TB_API long long tb_u8off(tb_u8slot *c, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5613; }
    { const char * tb_v5614 = "    if (c->nl == c->nb) return i;   // одна латиница: буква = байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5614; }
    { const char * tb_v5615 = "    const unsigned char *s = (const unsigned char *)c->p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5615; }
    { const char * tb_v5616 = "    long long li = c->li, bi = c->bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v5616; }
    { const char * tb_v5617 = "    if (i < li && i < li - i) { li = 0; bi = 0; }   // ближе к началу, чем к прошлому месту\n"; *(const char * *)tb_grow(v_lines) = tb_v5617; }
    { const char * tb_v5618 = "    while (li < i) { long long k = tb_u8n(s + bi); if (bi + k > c->nb) k = 1; bi += k; li++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5618; }
    { const char * tb_v5619 = "    while (li > i) {   // назад: на начало предыдущей буквы\n"; *(const char * *)tb_grow(v_lines) = tb_v5619; }
    { const char * tb_v5620 = "        long long b = bi - 1, back = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5620; }
    { const char * tb_v5621 = "        while (b > 0 && (s[b] & 0xC0) == 0x80 && back < 3) { b--; back++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5621; }
    { const char * tb_v5622 = "        if (b + tb_u8n(s + b) != bi) b = bi - 1;   // не сложилось в букву — один байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5622; }
    { const char * tb_v5623 = "        bi = b; li--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5623; }
    { const char * tb_v5624 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5624; }
    { const char * tb_v5625 = "    c->li = li; c->bi = bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v5625; }
    { const char * tb_v5626 = "    return bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v5626; }
    { const char * tb_v5627 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5627; }
    { const char * tb_v5628 = "// буквы из двух байт (русские, греческие...): готовые строки, как tb_chars для латиницы\n"; *(const char * *)tb_grow(v_lines) = tb_v5628; }
    { const char * tb_v5629 = "TB_API char tb_chars2[2048 * 4];\n"; *(const char * *)tb_grow(v_lines) = tb_v5629; }
    { const char * tb_v5630 = "TB_API const char *tb_u8text(const char *p, long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5630; }
    { const char * tb_v5631 = "    if (n == 1) return tb_chr((unsigned char)p[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5631; }
    { const char * tb_v5632 = "    if (n == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5632; }
    { const char * tb_v5633 = "        unsigned cp = (((unsigned char)p[0] & 0x1F) << 6) | ((unsigned char)p[1] & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v5633; }
    { const char * tb_v5634 = "        char *t = tb_chars2 + cp * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5634; }
    { const char * tb_v5635 = "        if (!t[0]) { t[1] = p[1]; t[2] = 0; __atomic_store_n(&t[0], p[0], __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5635; }
    { const char * tb_v5636 = "        return t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5636; }
    { const char * tb_v5637 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5637; }
    { const char * tb_v5638 = "    char *r = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v5638; }
    { const char * tb_v5639 = "    memcpy(r, p, n); r[n] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5639; }
    { const char * tb_v5640 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5640; }
    { const char * tb_v5641 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5641; }
    { const char * tb_v5642 = "// s[i]: буква номер i; n — длина в байтах, если компилятор её знает (текст, в который дописывают), иначе -1\n"; *(const char * *)tb_grow(v_lines) = tb_v5642; }
    { const char * tb_v5643 = "TB_API const char *tb_char_at(const char *s, long long i, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5643; }
    { const char * tb_v5644 = "    tb_u8slot *c = tb_u8info(s, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5644; }
    { const char * tb_v5645 = "    if (i < 0 || i >= c->nl) tb_crash(line, \"номер за пределами текста\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5645; }
    { const char * tb_v5646 = "    if (c->nl == c->nb) return tb_chr((unsigned char)s[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v5646; }
    { const char * tb_v5647 = "    long long b = tb_u8off(c, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5647; }
    { const char * tb_v5648 = "    long long k = tb_u8n((const unsigned char *)s + b);\n"; *(const char * *)tb_grow(v_lines) = tb_v5648; }
    { const char * tb_v5649 = "    if (b + k > c->nb) k = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5649; }
    { const char * tb_v5650 = "    return tb_u8text(s + b, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v5650; }
    { const char * tb_v5651 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5651; }
    { const char * tb_v5652 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5652; }
    { const char * tb_v5653 = "TB_API const char *tb_u8take(const char *s, long long *i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5653; }
    { const char * tb_v5654 = "    const unsigned char *p = (const unsigned char *)s + *i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5654; }
    { const char * tb_v5655 = "    if (*p < 0x80) return tb_chr(*p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5655; }
    { const char * tb_v5656 = "    long long k = tb_u8n(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5656; }
    { const char * tb_v5657 = "    *i += k - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5657; }
