    { const char * tb_v5659 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5659; }
    { const char * tb_v5660 = "// s += b: дописать в конец своей памяти s, а не собирать третий текст из двух.\n"; *(const char * *)tb_grow(v_lines) = tb_v5660; }
    { const char * tb_v5661 = "// *rl — длина s в своей памяти (-1: своей памяти нет, s могли сохранить где-то ещё — сначала копия),\n"; *(const char * *)tb_grow(v_lines) = tb_v5661; }
    { const char * tb_v5662 = "// *rc — сколько там места.\n"; *(const char * *)tb_grow(v_lines) = tb_v5662; }
    { const char * tb_v5663 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5663; }
    { const char * tb_v5664 = "// число цифрами в конец буфера d[24]: вернёт начало цифр, длину — в *n\n"; *(const char * *)tb_grow(v_lines) = tb_v5664; }
    { const char * tb_v5665 = "TB_INL const char *tb_digits(long long x, char *d, long long *n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5665; }
    { const char * tb_v5666 = "    unsigned long long u = x < 0 ? 0ULL - (unsigned long long)x : (unsigned long long)x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5666; }
    { const char * tb_v5667 = "    char *p = d + 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v5667; }
    { const char * tb_v5668 = "    do { *--p = (char)('0' + u % 10); u /= 10; } while (u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5668; }
    { const char * tb_v5669 = "    if (x < 0) *--p = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v5669; }
    { const char * tb_v5670 = "    *n = d + 24 - p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5670; }
    { const char * tb_v5671 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5671; }
    { const char * tb_v5672 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5672; }
    { const char * tb_v5673 = "TB_INL void tb_app(const char **p, long long *rl, long long *rc, const char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5673; }
    { const char * tb_v5674 = "    tb_app_n(p, rl, rc, b, (long long)strlen(b));\n"; *(const char * *)tb_grow(v_lines) = tb_v5674; }
    { const char * tb_v5675 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5675; }
    { const char * tb_v5676 = "// дописать число: цифры пишутся прямо в конец, без отдельного текста\n"; *(const char * *)tb_grow(v_lines) = tb_v5676; }
    { const char * tb_v5677 = "TB_INL void tb_app_i(const char **p, long long *rl, long long *rc, long long x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5677; }
    { const char * tb_v5678 = "    char d[24]; int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5678; }
    { const char * tb_v5679 = "    unsigned long long u = x < 0 ? 0ULL - (unsigned long long)x : (unsigned long long)x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5679; }
    { const char * tb_v5680 = "    do { d[23 - n++] = (char)('0' + u % 10); u /= 10; } while (u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5680; }
    { const char * tb_v5681 = "    if (x < 0) d[23 - n++] = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v5681; }
    { const char * tb_v5682 = "    tb_app_n(p, rl, rc, d + 24 - n, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5682; }
    { const char * tb_v5683 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5683; }
    { const char * tb_v5684 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5684; }
    { const char * tb_v5685 = "// ядро отдаёт свой кусок в общий текст: если общий ещё пустой — забирает память куска целиком, без копии\n"; *(const char * *)tb_grow(v_lines) = tb_v5685; }
    { const char * tb_v5686 = "TB_API void tb_app_take(const char **p, long long *rl, long long *rc, const char *b, long long brl, long long brc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5686; }
    { const char * tb_v5687 = "    if (*rl < 0 && (*p)[0] == 0 && brl >= 0) { *p = b; *rl = brl; *rc = brc; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5687; }
    { const char * tb_v5688 = "    tb_app_n(p, rl, rc, b, brl >= 0 ? brl : (long long)strlen(b));\n"; *(const char * *)tb_grow(v_lines) = tb_v5688; }
    { const char * tb_v5689 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5689; }
    { const char * tb_v5690 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5690; }
    { const char * tb_v5691 = "    char *s = (char *)*p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5691; }
    { const char * tb_v5692 = "    if (*rl < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5692; }
    { const char * tb_v5693 = "        long long la = (long long)strlen(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v5693; }
    { const char * tb_v5694 = "        long long cap = 2 * (la + lb) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5694; }
    { const char * tb_v5695 = "        if (cap < 64) cap = 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v5695; }
    { const char * tb_v5696 = "        char *r = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v5696; }
    { const char * tb_v5697 = "        memcpy(r, s, la);\n"; *(const char * *)tb_grow(v_lines) = tb_v5697; }
    { const char * tb_v5698 = "        memcpy(r + la, b, lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5698; }
    { const char * tb_v5699 = "        r[la + lb] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5699; }
    { const char * tb_v5700 = "        *p = r; *rl = la + lb; *rc = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5700; }
    { const char * tb_v5701 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5701; }
    { const char * tb_v5702 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5702; }
    { const char * tb_v5703 = "    long long need = *rl + lb + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5703; }
    { const char * tb_v5704 = "    if (need > *rc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5704; }
    { const char * tb_v5705 = "        long long cap = 2 * need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5705; }
    { const char * tb_v5706 = "        long long off = (b >= s && b < s + *rc) ? b - s : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5706; }
