    { const char * tb_v6307 = "    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v6307; }
    { const char * tb_v6308 = "    return (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;\n"; *(const char * *)tb_grow(v_lines) = tb_v6308; }
    { const char * tb_v6309 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6309; }
    { const char * tb_v6310 = "TB_API void tb_wait_ms(long long n) { fflush(stdout); if (n > 0) usleep((useconds_t)(n * 1000)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6310; }
    { const char * tb_v6311 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6311; }
    { const char * tb_v6312 = "TB_API unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6312; }
    { const char * tb_v6313 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v6313; }
    { const char * tb_v6314 = "TB_API long long tb_rgb(long long r, long long g, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6314; }
    { const char * tb_v6315 = "    r = r < 0 ? 0 : r > 255 ? 255 : r; g = g < 0 ? 0 : g > 255 ? 255 : g; b = b < 0 ? 0 : b > 255 ? 255 : b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6315; }
    { const char * tb_v6316 = "    return (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6316; }
    { const char * tb_v6317 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6317; }
    { const char * tb_v6318 = "// цвет с непрозрачностью a: 255 — сплошной (как rgb), 0 — не виден. Рисование смешивает его с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v6318; }
    { const char * tb_v6319 = "TB_API long long tb_rgba(long long r, long long g, long long b, long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6319; }
    { const char * tb_v6320 = "    a = a < 0 ? 0 : a > 255 ? 255 : a;\n"; *(const char * *)tb_grow(v_lines) = tb_v6320; }
    { const char * tb_v6321 = "    return ((255 - a) << 24) | tb_rgb(r, g, b);\n"; *(const char * *)tb_grow(v_lines) = tb_v6321; }
    { const char * tb_v6322 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6322; }
    { const char * tb_v6323 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v6323; }
    { const char * tb_v6324 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6324; }
    { const char * tb_v6325 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6325; }
    { const char * tb_v6326 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6326; }
    { const char * tb_v6327 = "        unsigned lo, hi; __asm__ volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n"; *(const char * *)tb_grow(v_lines) = tb_v6327; }
    { const char * tb_v6328 = "        tb_rand_state = ((unsigned long long)hi << 32 | lo) ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6328; }
    { const char * tb_v6329 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6329; }
    { const char * tb_v6330 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v6330; }
    { const char * tb_v6331 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6331; }
    { const char * tb_v6332 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6332; }
    { const char * tb_v6333 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6333; }
    { const char * tb_v6334 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6334; }
    { const char * tb_v6335 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v6335; }
    { const char * tb_v6336 = "    unsigned long long span = (unsigned long long)(b - a) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6336; }
    { const char * tb_v6337 = "    return span == 0 ? (long long)tb_rand_state : a + (long long)(tb_rand_state % span);\n"; *(const char * *)tb_grow(v_lines) = tb_v6337; }
    { const char * tb_v6338 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6338; }
