    { const char * tb_v6365 = "// ---------- sort ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6365; }
    { const char * tb_v6366 = "TB_API int tb_cmp_int(const void *a, const void *b) { long long x = *(const long long *)a, y = *(const long long *)b; return (x > y) - (x < y); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6366; }
