    { const char * tb_v6369 = "TB_API tb_list *tb_copy(tb_list *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6369; }
    { const char * tb_v6370 = "    if (l->size == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6370; }
    { const char * tb_v6371 = "        tb_list *r = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v6371; }
