    { const char * tb_v6373 = "        r->len = l->len; r->cap = l->cap; r->size = 0; r->data = tb_mem_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v6373; }
    { const char * tb_v6374 = "        memcpy(r->data, l->data, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v6374; }
    { const char * tb_v6375 = "        return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6375; }
