    { const char * tb_v6380 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6380; }
    { const char * tb_v6381 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v6381; }
    { const char * tb_v6382 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v6382; }
    { const char * tb_v6383 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v6383; }
    { const char * tb_v6384 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v6384; }
    { const char * tb_v6385 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6385; }
    { const char * tb_v6386 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v6386; }
    { const char * tb_v6387 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v6387; }
    { const char * tb_v6388 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v6388; }
    { const char * tb_v6389 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v6389; }
    { const char * tb_v6390 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6390; }
    { const char * tb_v6391 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v6391; }
    { const char * tb_v6392 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6392; }
    { const char * tb_v6393 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6393; }
    { const char * tb_v6394 = "    if (texts) for (long long i = 0; i < l->len; i++) tb_export(((char **)l->data)[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6394; }
    { const char * tb_v6395 = "    tb_export(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v6395; }
    { const char * tb_v6396 = "    tb_export(l);\n"; *(const char * *)tb_grow(v_lines) = tb_v6396; }
    { const char * tb_v6397 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6397; }
    { const char * tb_v6398 = "TB_API void tb_export_dict(tb_dict *d, int ktext, int vtext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6398; }
    { const char * tb_v6399 = "    if (!d) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6399; }
    { const char * tb_v6400 = "    tb_export_list(d->keys, ktext);\n"; *(const char * *)tb_grow(v_lines) = tb_v6400; }
    { const char * tb_v6401 = "    tb_export_list(d->vals, vtext);\n"; *(const char * *)tb_grow(v_lines) = tb_v6401; }
    { const char * tb_v6402 = "    tb_export(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v6402; }
    { const char * tb_v6403 = "    tb_export(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v6403; }
    { const char * tb_v6404 = "    tb_export(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6404; }
    { const char * tb_v6405 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6405; }
    { const char * tb_v6406 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6406; }
    { const char * tb_v6407 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6407; }
    { const char * tb_v6408 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v6408; }
    { const char * tb_v6409 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v6409; }
    { const char * tb_v6410 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v6410; }
    { const char * tb_v6411 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6411; }
    { const char * tb_v6412 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6412; }
    { const char * tb_v6413 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6413; }
    { const char * tb_v6414 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6414; }
    { const char * tb_v6415 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6415; }
    { const char * tb_v6416 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v6416; }
    { const char * tb_v6417 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6417; }
    { const char * tb_v6418 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6418; }
    { const char * tb_v6419 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6419; }
    { const char * tb_v6420 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6420; }
    { const char * tb_v6421 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6421; }
    { const char * tb_v6422 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6422; }
    { const char * tb_v6423 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6423; }
    { const char * tb_v6424 = "    return *(const long long *)a == *(const long long *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6424; }
    { const char * tb_v6425 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6425; }
    { const char * tb_v6426 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6426; }
    { const char * tb_v6427 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6427; }
    { const char * tb_v6428 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v6428; }
    { const char * tb_v6429 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6429; }
    { const char * tb_v6430 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6430; }
    { const char * tb_v6431 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6431; }
    { const char * tb_v6432 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v6432; }
    { const char * tb_v6433 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6433; }
    { const char * tb_v6434 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6434; }
    { const char * tb_v6435 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6435; }
    { const char * tb_v6436 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v6436; }
    { const char * tb_v6437 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6437; }
    { const char * tb_v6438 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6438; }
    { const char * tb_v6439 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v6439; }
    { const char * tb_v6440 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6440; }
    { const char * tb_v6441 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6441; }
    { const char * tb_v6442 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v6442; }
    { const char * tb_v6443 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6443; }
    { const char * tb_v6444 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6444; }
    { const char * tb_v6445 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6445; }
