    { const char * tb_v6613 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
    { const char * tb_v6614 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6614; }
    { const char * tb_v6615 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6615; }
    { const char * tb_v6616 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v6616; }
    { const char * tb_v6617 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6617; }
    { const char * tb_v6618 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6618; }
