    { const char * tb_v6782 = "    uint64_t old = __atomic_load_n(q, __ATOMIC_SEQ_CST), nw;\n"; *(const char * *)tb_grow(v_lines) = tb_v6782; }
    { const char * tb_v6783 = "    do {\n"; *(const char * *)tb_grow(v_lines) = tb_v6783; }
