    { const char * tb_v6809 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6809; }
    { const char * tb_v6810 = "        const char *e = getenv(\"TB_MEM_CHECK\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6810; }
    { const char * tb_v6811 = "        tb_mem_check = e && e[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v6811; }
