    { const char * tb_v6816 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6816; }
    { const char * tb_v6817 = "static void tb_mem_lock(void) { while (__sync_lock_test_and_set(&tb_mem_spin, 1)) { } }\n"; *(const char * *)tb_grow(v_lines) = tb_v6817; }
