    { const char * tb_v6827 = "TB_API void tb_mem_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6827; }
    { const char * tb_v6828 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6828; }
    { const char * tb_v6829 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6829; }
    { const char * tb_v6830 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6830; }
    { const char * tb_v6831 = "    if (n && tb_mem_check) fprintf(stderr, tb_tr(\"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\"), n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v6831; }
    { const char * tb_v6832 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6832; }
    { const char * tb_v6833 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v6833; }
    { const char * tb_v6834 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6834; }
    { const char * tb_v6835 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6835; }
    { const char * tb_v6836 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v6836; }
    { const char * tb_v6837 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6837; }
    { const char * tb_v6838 = "        tb_memb *b = &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6838; }
    { const char * tb_v6839 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v6839; }
    { const char * tb_v6840 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6840; }
    { const char * tb_v6841 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6841; }
    { const char * tb_v6842 = "            char buf[400];\n"; *(const char * *)tb_grow(v_lines) = tb_v6842; }
    { const char * tb_v6843 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v6843; }
    { const char * tb_v6844 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v6844; }
    { const char * tb_v6845 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6845; }
    { const char * tb_v6846 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v6846; }
    { const char * tb_v6847 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6847; }
    { const char * tb_v6848 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v6848; }
    { const char * tb_v6849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6849; }
    { const char * tb_v6850 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6850; }
    { const char * tb_v6851 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6851; }
    { const char * tb_v6852 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6852; }
    { const char * tb_v6853 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6853; }
    { const char * tb_v6854 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
    { const char * tb_v6855 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v6855; }
    { const char * tb_v6856 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6856; }
    { const char * tb_v6857 = "TB_INL long long tb_rd16(long long a, int line) { TB_TOUCH(a, 2); return *(volatile uint16_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6857; }
    { const char * tb_v6858 = "TB_INL long long tb_rd32(long long a, int line) { TB_TOUCH(a, 4); return *(volatile uint32_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6858; }
    { const char * tb_v6859 = "TB_INL long long tb_rd64(long long a, int line) { TB_TOUCH(a, 8); return (long long)*(volatile uint64_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6859; }
