    { const char * tb_v6862 = "TB_INL void tb_wr32(long long a, long long v, int line) { TB_TOUCH(a, 4); *(volatile uint32_t *)(uintptr_t)a = (uint32_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6862; }
