    { const char * tb_v6952 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6952; }
    { const char * tb_v6953 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6953; }
