    { const char * tb_v6974 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6974; }
    { const char * tb_v6975 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v6975; }
    { const char * tb_v6976 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6976; }
    { const char * tb_v6977 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v6977; }
    { const char * tb_v6978 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
