    { const char * tb_v6982 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6982; }
    { const char * tb_v6983 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6983; }
    { const char * tb_v6984 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6984; }
    { const char * tb_v6985 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v6985; }
    { const char * tb_v6986 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v6986; }
    { const char * tb_v6987 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v6987; }
    { const char * tb_v6988 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v6988; }
    { const char * tb_v6989 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v6989; }
    { const char * tb_v6990 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v6990; }
    { const char * tb_v6991 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v6991; }
    { const char * tb_v6992 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6992; }
    { const char * tb_v6993 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v6993; }
    { const char * tb_v6994 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6994; }
    { const char * tb_v6995 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6995; }
    { const char * tb_v6996 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6996; }
    { const char * tb_v6997 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v6997; }
    { const char * tb_v6998 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
    { const char * tb_v7000 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7000; }
    { const char * tb_v7001 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v7001; }
    { const char * tb_v7002 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7002; }
    { const char * tb_v7003 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7003; }
    { const char * tb_v7004 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v7004; }
    { const char * tb_v7005 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7005; }
    { const char * tb_v7006 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v7006; }
    { const char * tb_v7007 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v7007; }
    { const char * tb_v7008 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7008; }
    { const char * tb_v7009 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v7009; }
    { const char * tb_v7010 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7010; }
    { const char * tb_v7011 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7011; }
    { const char * tb_v7012 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7012; }
    { const char * tb_v7013 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v7013; }
    { const char * tb_v7014 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7014; }
    { const char * tb_v7015 = "        char buf[400];\n"; *(const char * *)tb_grow(v_lines) = tb_v7015; }
