    { const char * tb_v7095 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v7095; }
    { const char * tb_v7096 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7096; }
