    { const char * tb_v7102 = "static inline void tb_shape_put(uintptr_t p, int nb, uint64_t v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7102; }
    { const char * tb_v7103 = "    if (nb == 1) *(volatile uint8_t *)p = (uint8_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7103; }
