    { const char * tb_v7137 = "    static const char *uns[9] = { 0, \"число не влезает в поле u8: от 0 до 255\", \"число не влезает в поле u16: от 0 до 65 535\", 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v7137; }
    { const char * tb_v7138 = "        \"число не влезает в поле u32: от 0 до 4 294 967 295\", 0, 0, 0, \"в поле u64 не бывает чисел меньше нуля\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v7138; }
    { const char * tb_v7139 = "    static const char *sig[9] = { 0, \"число не влезает в поле i8: от -128 до 127\", \"число не влезает в поле i16: от -32 768 до 32 767\", 0,\n"; *(const char * *)tb_grow(v_lines) = tb_v7139; }
