    { const char * tb_v7144 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7144; }
    { const char * tb_v7145 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v7145; }
