    { const char * tb_v7179 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v7179; }
    { const char * tb_v7180 = "    if (!tb_in_irq && s->nlocks < 8) s->locks[s->nlocks++] = l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7180; }
    { const char * tb_v7181 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7181; }
