    { const char * tb_v7539 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7539; }
    { const char * tb_v7540 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v7540; }
    { const char * tb_v7541 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v7541; }
    { const char * tb_v7542 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v7542; }
    { const char * tb_v7543 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v7543; }
    { const char * tb_v7544 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7544; }
    { const char * tb_v7545 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7545; }
    { const char * tb_v7546 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7546; }
    { const char * tb_v7547 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7547; }
    { const char * tb_v7548 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7548; }
    { const char * tb_v7549 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7549; }
    { const char * tb_v7550 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7550; }
    { const char * tb_v7551 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7551; }
    { const char * tb_v7552 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7552; }
    { const char * tb_v7553 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7553; }
    { const char * tb_v7554 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7554; }
    { const char * tb_v7555 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v7555; }
    { const char * tb_v7556 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7556; }
    { const char * tb_v7557 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7557; }
    { const char * tb_v7558 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7558; }
    { const char * tb_v7559 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7559; }
    { const char * tb_v7560 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7560; }
    { const char * tb_v7561 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7561; }
    { const char * tb_v7562 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7562; }
    { const char * tb_v7563 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v7563; }
    { const char * tb_v7564 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v7564; }
    { const char * tb_v7565 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7565; }
    { const char * tb_v7566 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7566; }
    { const char * tb_v7567 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7567; }
    { const char * tb_v7568 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v7568; }
    { const char * tb_v7569 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v7569; }
    { const char * tb_v7570 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7570; }
    { const char * tb_v7571 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7571; }
    { const char * tb_v7572 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7572; }
    { const char * tb_v7573 = "    for (int l = 1; l < 16; l++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7573; }
