    { const char * tb_v7588 = "    static const unsigned char order[19] = { 16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7588; }
    { const char * tb_v7589 = "    int last;\n"; *(const char * *)tb_grow(v_lines) = tb_v7589; }
    { const char * tb_v7590 = "    do {\n"; *(const char * *)tb_grow(v_lines) = tb_v7590; }
