    { const char * tb_v7593 = "        if (type == 0) {   // без сжатия\n"; *(const char * *)tb_grow(v_lines) = tb_v7593; }
    { const char * tb_v7594 = "            z->bits >>= z->nb & 7; z->nb -= z->nb & 7;\n"; *(const char * *)tb_grow(v_lines) = tb_v7594; }
    { const char * tb_v7595 = "            unsigned len = tb_zbits(z, 16), nlen = tb_zbits(z, 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v7595; }
    { const char * tb_v7596 = "            if ((len ^ 0xFFFF) != nlen) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7596; }
    { const char * tb_v7597 = "            while (len-- && !z->err) tb_zput(z, (unsigned char)tb_zbits(z, 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v7597; }
    { const char * tb_v7598 = "        } else if (type == 1 || type == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7598; }
    { const char * tb_v7599 = "            tb_huff lh, dh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7599; }
