    { const char * tb_v8223 = "// image_scaled(картинка, w, h): новая картинка другого размера (уменьшение — среднее по площади,\n"; *(const char * *)tb_grow(v_lines) = tb_v8223; }
    { const char * tb_v8224 = "// увеличение — ближайшая точка). Так фото с диска влезает в окно, значок — в свой квадрат.\n"; *(const char * *)tb_grow(v_lines) = tb_v8224; }
    { const char * tb_v8225 = "TB_API long long tb_image_scaled(long long i, long long w, long long h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8225; }
    { const char * tb_v8226 = "    if (i < 0 || i >= tb_nimg) { tb_err = \"нет такой картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8226; }
    { const char * tb_v8227 = "    if (w < 1 || h < 1 || w * h > (1ll << 26)) { tb_err = \"такой размер не годится\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "    int sw = tb_imgs[i].w, sh = tb_imgs[i].h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
