    { const char * tb_v8726 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8726; }
    { const char * tb_v8727 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8727; }
    { const char * tb_v8728 = "    if (tb_mseen) { tb_mdx += x - tb_mx; tb_mdy += y - tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8728; }
    { const char * tb_v8729 = "    tb_mseen = 1; tb_mx = x; tb_my = y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8729; }
    { const char * tb_v8730 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8730; }
    { const char * tb_v8731 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v8731; }
    { const char * tb_v8732 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8732; }
