    { const char * tb_v8734 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8734; }
    { const char * tb_v8735 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8735; }
    { const char * tb_v8736 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8736; }
    { const char * tb_v8737 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v8737; }
    { const char * tb_v8738 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8738; }
    { const char * tb_v8739 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v8739; }
    { const char * tb_v8740 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8740; }
    { const char * tb_v8741 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8741; }
    { const char * tb_v8742 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8742; }
    { const char * tb_v8743 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, tb_tr(\"окно: рисует %s\\n\"), what);\n"; *(const char * *)tb_grow(v_lines) = tb_v8743; }
    { const char * tb_v8744 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8744; }
