    { const char * tb_v8746 = "    fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\"), tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v8746; }
    { const char * tb_v8747 = "    if (tb_gpu_shskip) fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров со своими шейдерами (не сверялись): %lld\\n\"), tb_gpu_shskip);\n"; *(const char * *)tb_grow(v_lines) = tb_v8747; }
    { const char * tb_v8748 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8748; }
    { const char * tb_v8749 = "// ---- gpu func (1.3): шейдеры программы — их собрал компилятор Tachbit из gpu func ----\n"; *(const char * *)tb_grow(v_lines) = tb_v8749; }
    { const char * tb_v8750 = "// У каждого: имя, вид (0 — углы, 1 — точка), функция для процессора, SPIR-V, имена настроек по порядку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8750; }
    { const char * tb_v8751 = "// Metal берёт все шейдеры из одного текста tb_sh_msl. Сетка со своим шейдером рисуется обычными\n"; *(const char * *)tb_grow(v_lines) = tb_v8751; }
    { const char * tb_v8752 = "// дробными числами (не точка в точку с процессором): в пачке это фигура m = 7 — x0 номер записи,\n"; *(const char * *)tb_grow(v_lines) = tb_v8752; }
    { const char * tb_v8753 = "// y0 шейдер углов, x1 шейдер точки, y1 сколько углов; углы сетки лежат в своём буфере видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v8753; }
    { const char * tb_v8754 = "// R — своя запись draw_mesh (лампы, картинки, тени), T — точки всех картинок (tb_imgpx), S — карты теней (tb_shm)\n"; *(const char * *)tb_grow(v_lines) = tb_v8754; }
    { const char * tb_v8755 = "typedef void (*tb_shfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io);\n"; *(const char * *)tb_grow(v_lines) = tb_v8755; }
    { const char * tb_v8756 = "// Вид 2 — шейдер экрана (screen_shader): функция (io, кадр, глубина), в пачке фигура m = 8 — x0 номер записи, x1 шейдер;\n"; *(const char * *)tb_grow(v_lines) = tb_v8756; }
    { const char * tb_v8757 = "// вид 3 — вершины для экрана (один треугольник на всё окно). sv — настройки шейдера экрана (screen_set)\n"; *(const char * *)tb_grow(v_lines) = tb_v8757; }
    { const char * tb_v8758 = "typedef void (*tb_scrfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io, const uint32_t *scr, const float *scz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8758; }
    { const char * tb_v8759 = "typedef struct { const char *name; int stage; tb_shfn fn; const uint32_t *spv; size_t bytes; int nsets; char sets[8][32]; float sv[8]; } tb_shader_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8759; }
    { const char * tb_v8760 = "enum { TB_SH_MAX = 64, TB_SHR_CAP = 4096, TB_SHR_N = 224, TB_SHB_CAP = 12 * 32768 };   // TB_SHB_CAP — числа матриц костей на набор\n"; *(const char * *)tb_grow(v_lines) = tb_v8760; }
    { const char * tb_v8761 = "TB_API tb_shader_t tb_shaders[TB_SH_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v8761; }
    { const char * tb_v8762 = "TB_API int tb_nshaders = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8762; }
    { const char * tb_v8763 = "TB_API const char *tb_sh_msl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8763; }
    { const char * tb_v8764 = "TB_API float *tb_shrecs = 0;          // записи текущего набора: TB_SHR_N чисел на draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8764; }
    { const char * tb_v8765 = "TB_API int tb_shrn = 0;            // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8765; }
    { const char * tb_v8766 = "TB_API float *tb_shbones = 0;      // матрицы костей текущего набора (после всех записей в том же буфере)\n"; *(const char * *)tb_grow(v_lines) = tb_v8766; }
    { const char * tb_v8767 = "TB_API long long tb_shbn = 0, tb_shbase = 0;   // сколько чисел занято; где они начинаются в буфере (номер числа)\n"; *(const char * *)tb_grow(v_lines) = tb_v8767; }
    { const char * tb_v8768 = "#define TB_SHB_AT(map) do { tb_shbase = (long long)TB_SHR_N * TB_SHR_CAP * TB_GSLOTS + (long long)tb_gslot * TB_SHB_CAP; tb_shbones = (map) + tb_shbase; tb_shbn = 0; } while (0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8768; }
    { const char * tb_v8769 = "TB_API int tb_sh_frame = 0;        // в кадре была сетка со своим шейдером: TB_GPU_CHECK кадр не сверяет\n"; *(const char * *)tb_grow(v_lines) = tb_v8769; }
    { const char * tb_v8770 = "TB_API void tb_sh_lib(const char *msl) { tb_sh_msl = msl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8770; }
    { const char * tb_v8771 = "TB_API void tb_sh_reg(const char *name, int stage, tb_shfn fn, const uint32_t *spv, size_t bytes, const char *sets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8771; }
    { const char * tb_v8772 = "    if (tb_nshaders == TB_SH_MAX) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8772; }
    { const char * tb_v8773 = "    tb_shader_t *s = &tb_shaders[tb_nshaders++];\n"; *(const char * *)tb_grow(v_lines) = tb_v8773; }
    { const char * tb_v8774 = "    memset(s, 0, sizeof *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v8774; }
    { const char * tb_v8775 = "    s->name = name; s->stage = stage; s->fn = fn; s->spv = spv; s->bytes = bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v8775; }
    { const char * tb_v8776 = "    for (const char *p = sets; *p && s->nsets < 8;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8776; }
    { const char * tb_v8777 = "        int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8777; }
    { const char * tb_v8778 = "        while (p[n] && p[n] != ',') n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8778; }
    { const char * tb_v8779 = "        int k = n > 31 ? 31 : n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8779; }
    { const char * tb_v8780 = "        memcpy(s->sets[s->nsets], p, (size_t)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v8780; }
    { const char * tb_v8781 = "        s->sets[s->nsets][k] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8781; }
    { const char * tb_v8782 = "        s->nsets++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8782; }
    { const char * tb_v8783 = "        p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8783; }
    { const char * tb_v8784 = "        if (*p == ',') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8784; }
    { const char * tb_v8785 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8785; }
    { const char * tb_v8786 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8786; }
    { const char * tb_v8787 = "TB_API int tb_sh_find(const char *name, int stage) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8787; }
    { const char * tb_v8788 = "    for (int i = 0; i < tb_nshaders; i++) if (tb_shaders[i].stage == stage && strcmp(tb_shaders[i].name, name) == 0) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8788; }
    { const char * tb_v8789 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8789; }
    { const char * tb_v8790 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8790; }
    { const char * tb_v8791 = "// свои у каждой системы: готова ли видеокарта; углы сетки в её буфер (старый отдаётся); фигура m = 7 в пачку\n"; *(const char * *)tb_grow(v_lines) = tb_v8791; }
    { const char * tb_v8792 = "TB_API int tb_gpu_sh_ready(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v8792; }
    { const char * tb_v8793 = "TB_API void *tb_gpu_sh_vbuf(void *old, const float *v, long long nfloats);\n"; *(const char * *)tb_grow(v_lines) = tb_v8793; }
    { const char * tb_v8794 = "TB_API void tb_gpu_sh_add(void *vb, int cs, int ps, long long nverts, int nowrite);   // nowrite: глубину не писать (прозрачная сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v8794; }
    { const char * tb_v8795 = "TB_API int tb_gpu_scr_ready(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v8795; }
    { const char * tb_v8796 = "// ---- тени для gpu func: карта солнца (1024 × 1024) и кубы ламп (6 × 256 × 256, до 4 ламп) по 16 бит —\n"; *(const char * *)tb_grow(v_lines) = tb_v8796; }
    { const char * tb_v8797 = "// две глубины в слове; у каждого набора видеокарты свои (прошлые кадры ещё рисуются). Начало — число 207 записи\n"; *(const char * *)tb_grow(v_lines) = tb_v8797; }
    { const char * tb_v8798 = "enum { TB_LSM_N = 256, TB_LSM_MAX = 4 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8798; }
    { const char * tb_v8799 = "#define TB_SHM_SLOT ((size_t)1024 * 1024 + (size_t)TB_LSM_MAX * 6 * TB_LSM_N * TB_LSM_N)\n"; *(const char * *)tb_grow(v_lines) = tb_v8799; }
    { const char * tb_v8800 = "TB_API uint32_t *tb_shm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8800; }
    { const char * tb_v8801 = "TB_API int tb_lshadow[8];             // light_shadow: лампа даёт тени\n"; *(const char * *)tb_grow(v_lines) = tb_v8801; }
    { const char * tb_v8802 = "TB_API int tb_lsm_of[8] = { -1, -1, -1, -1, -1, -1, -1, -1 };   // куб лампы в картах этой сцены\n"; *(const char * *)tb_grow(v_lines) = tb_v8802; }
    { const char * tb_v8803 = "TB_API int tb_shm_sun = 0;            // в картах этой сцены есть солнце\n"; *(const char * *)tb_grow(v_lines) = tb_v8803; }
    { const char * tb_v8804 = "TB_API long long tb_shm_batch = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8804; }
    { const char * tb_v8805 = "TB_API uint32_t *tb_gpu_shm(void);    // своя у каждой системы: память карт, которую видит видеокарта (0 — нет)\n"; *(const char * *)tb_grow(v_lines) = tb_v8805; }
    { const char * tb_v8806 = "TB_API void tb_gpu_scr_add(int ps);\n"; *(const char * *)tb_grow(v_lines) = tb_v8806; }
    { const char * tb_v8807 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v8807; }
    { const char * tb_v8808 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v8808; }
    { const char * tb_v8809 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8809; }
    { const char * tb_v8810 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v8810; }
    { const char * tb_v8811 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v8811; }
    { const char * tb_v8812 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8812; }
    { const char * tb_v8813 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8813; }
    { const char * tb_v8814 = "    if (tb_sh_frame) { tb_sh_frame = 0; tb_gpu_shskip++; return; }   // свои шейдеры: дробные числа, точка в точку не сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v8814; }
    { const char * tb_v8815 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8815; }
    { const char * tb_v8816 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8816; }
    { const char * tb_v8817 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8817; }
    { const char * tb_v8818 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8818; }
    { const char * tb_v8819 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8819; }
