    { const char * tb_v8842 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8842; }
    { const char * tb_v8843 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8843; }
    { const char * tb_v8844 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8844; }
    { const char * tb_v8845 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8845; }
    { const char * tb_v8846 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8846; }
    { const char * tb_v8847 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8847; }
