    { const char * tb_v8851 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8851; }
    { const char * tb_v8852 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8852; }
    { const char * tb_v8853 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8853; }
    { const char * tb_v8854 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8854; }
    { const char * tb_v8855 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8855; }
    { const char * tb_v8856 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8856; }
    { const char * tb_v8857 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8857; }
    { const char * tb_v8858 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8858; }
    { const char * tb_v8859 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8859; }
    { const char * tb_v8860 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v8860; }
    { const char * tb_v8861 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v8861; }
    { const char * tb_v8862 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8862; }
    { const char * tb_v8863 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v8863; }
    { const char * tb_v8864 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v8864; }
    { const char * tb_v8865 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8865; }
    { const char * tb_v8866 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8866; }
    { const char * tb_v8867 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8867; }
    { const char * tb_v8868 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8868; }
    { const char * tb_v8869 = "// сглаженный угол (bit 29) или угол тени (bit 28): рисуется только квадрат x0..x1, y0..y1, центр (ox, oy) — угол между точками\n"; *(const char * *)tb_grow(v_lines) = tb_v8869; }
    { const char * tb_v8870 = "TB_API void tb_gpu_soft(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, long long c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8870; }
