    { const char * tb_v8875 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8875; }
    { const char * tb_v8876 = "    tb_gpu_add(x0, y0, x1, y1, ox, oy, (uint32_t)c, (1u << 30) | m);\n"; *(const char * *)tb_grow(v_lines) = tb_v8876; }
    { const char * tb_v8877 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8877; }
