    { const char * tb_v8883 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v8883; }
    { const char * tb_v8884 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8884; }
    { const char * tb_v8885 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v8885; }
