    { const char * tb_v8899 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8899; }
    { const char * tb_v8900 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8900; }
