    { const char * tb_v8904 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v8904; }
    { const char * tb_v8905 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8905; }
    { const char * tb_v8906 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8906; }
    { const char * tb_v8907 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8907; }
    { const char * tb_v8908 = "// 3 — «новый» треугольник, 4 — он же прозрачный (глубину не пишет)\n"; *(const char * *)tb_grow(v_lines) = tb_v8908; }
    { const char * tb_v8909 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 28) & 1u ? 3 + (int)((m >> 27) & 1u) : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8909; }
    { const char * tb_v8910 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8910; }
    { const char * tb_v8911 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8911; }
    { const char * tb_v8912 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v8912; }
    { const char * tb_v8913 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v8913; }
    { const char * tb_v8914 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = gt;\n"; *(const char * *)tb_grow(v_lines) = tb_v8914; }
    { const char * tb_v8915 = "    tb_gtex[gt] = *tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v8915; }
    { const char * tb_v8916 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (1u << 29) | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v8916; }
    { const char * tb_v8917 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8917; }
    { const char * tb_v8918 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8918; }
    { const char * tb_v8919 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8919; }
    { const char * tb_v8920 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8920; }
    { const char * tb_v8921 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8921; }
    { const char * tb_v8922 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v8922; }
