    { const char * tb_v12564 = "    static const char *names[7] = { \"arrowCursor\", \"pointingHandCursor\", \"IBeamCursor\", \"openHandCursor\", \"resizeLeftRightCursor\", \"resizeUpDownCursor\", \"arrowCursor\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v12564; }
