    { const char * tb_v12577 = "// ---------- Metal (Mac) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v12577; }
    { const char * tb_v12578 = "// Metal зовём так же, как Cocoa: через objc_msgSend. Шейдер (tb_msl выше, compiler/gpu/tb.metal)\n"; *(const char * *)tb_grow(v_lines) = tb_v12578; }
    { const char * tb_v12579 = "// Mac переводит сам при запуске. Сама библиотека Metal грузится через dlopen: нет её — процессор.\n"; *(const char * *)tb_grow(v_lines) = tb_v12579; }
