    { const char * tb_v12585 = "    psom, mbuf, grbuf, psot, gtbuf, psol, zsa, glbuf, smbuf; } tb_mtl;   // psom — сетки на видеокарте (tb_vert3), mbuf — сетки, grbuf — записи draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v12585; }
    { const char * tb_v12586 = "// дождаться всех кадров, которые видеокарта ещё рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v12586; }
    { const char * tb_v12587 = "TB_API void tb_mtl_idle(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12587; }
    { const char * tb_v12588 = "    for (int s = 0; s < TB_GSLOTS; s++)\n"; *(const char * *)tb_grow(v_lines) = tb_v12588; }
    { const char * tb_v12589 = "        if (tb_mtl.cbs[s]) { TB_MSG(void, tb_mtl.cbs[s], \"waitUntilCompleted\"); TB_MSG(void, tb_mtl.cbs[s], \"release\"); tb_mtl.cbs[s] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12589; }
