    { const char * tb_v12595 = "    unsigned long sz = tb_imgpx_n * 4 > 16 ? tb_imgpx_n * 4 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v12595; }
    { const char * tb_v12596 = "    tb_mtl.pbuf = ((id (*)(id, SEL, unsigned long, unsigned long))objc_msgSend)(tb_mtl.dev, sel_getUid(\"newBufferWithLength:options:\"), sz, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v12596; }
