    { const char * tb_v12608 = "    tb_mtl.mbuf = ((id (*)(id, SEL, unsigned long, unsigned long))objc_msgSend)(tb_mtl.dev, sel_getUid(\"newBufferWithLength:options:\"), sz, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v12608; }
    { const char * tb_v12609 = "    if (!tb_mtl.mbuf) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12609; }
    { const char * tb_v12610 = "    if (n > 0) tb_mesh_pack((int32_t *)TB_MSG(void *, tb_mtl.mbuf, \"contents\"));\n"; *(const char * *)tb_grow(v_lines) = tb_v12610; }
