    { const char * tb_v13606 = "TB_API int tb_gfx_menu_native(void) { return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13606; }
    { const char * tb_v13607 = "TB_API int tb_gfx_menu_add(int n, const char *top, const char *item, const char *key, int mods) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13607; }
    { const char * tb_v13608 = "    if (!tb_hwnd) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13608; }
