    { const char * tb_v13624 = "        snprintf(label, sizeof label, \"%s%s%s%s%s%s\", item, key[0] ? \"\\t\" : \"\", key[0] && (mods & 9) ? \"Ctrl+\" : \"\",\n"; *(const char * *)tb_grow(v_lines) = tb_v13624; }
    { const char * tb_v13625 = "            key[0] && (mods & 2) ? \"Shift+\" : \"\", key[0] && (mods & 4) ? \"Alt+\" : \"\", key);\n"; *(const char * *)tb_grow(v_lines) = tb_v13625; }
    { const char * tb_v13626 = "        if (key[0]) for (char *c = label + strlen(item) + 1; *c; c++) if (*c >= 'a' && *c <= 'z' && (c[1] == 0)) *c -= 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v13626; }
