    { const char * tb_v13855 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v13855; }
    { const char * tb_v13856 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v13856; }
    { const char * tb_v13857 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13857; }
    { const char * tb_v13858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13858; }
    { const char * tb_v13859 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13859; }
    { const char * tb_v13860 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v13860; }
    { const char * tb_v13861 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v13861; }
    { const char * tb_v13862 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13862; }
    { const char * tb_v13863 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13863; }
    { const char * tb_v13864 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v13864; }
    { const char * tb_v13865 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v13865; }
    { const char * tb_v13866 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v13866; }
