    { const char * tb_v13877 = "// буфер обмена X11: текст держит сама программа-владелец и отдаёт его по просьбе (SelectionRequest)\n"; *(const char * *)tb_grow(v_lines) = tb_v13877; }
    { const char * tb_v13878 = "TB_API char *tb_x_clip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13878; }
