    { const char * tb_v13944 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v13944; }
    { const char * tb_v13945 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13945; }
    { const char * tb_v13946 = "TB_API void tb_gfx_events(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13946; }
    { const char * tb_v13947 = "    if (tb_gpu_on) tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13947; }
    { const char * tb_v13948 = "    else XPutImage(tb_dpy, tb_xw, tb_xgc, tb_ximg, 0, 0, 0, 0, tb_gw, tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v13948; }
    { const char * tb_v13949 = "    int was = tb_wcur;\n"; *(const char * *)tb_grow(v_lines) = tb_v13949; }
    { const char * tb_v13950 = "    while (XPending(tb_dpy)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13950; }
    { const char * tb_v13951 = "        XEvent e; XNextEvent(tb_dpy, &e);\n"; *(const char * *)tb_grow(v_lines) = tb_v13951; }
    { const char * tb_v13952 = "        if (tb_wn > 1) { int w = tb_wfind((uintptr_t)e.xany.window); if (w >= 0) tb_wswitch(w); }   // событие другого окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13952; }
    { const char * tb_v13953 = "        if (e.type == SelectionRequest) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v13953; }
    { const char * tb_v13954 = "        else if (e.type == FocusOut) memset(tb_keys, 0, sizeof tb_keys);\n"; *(const char * *)tb_grow(v_lines) = tb_v13954; }
    { const char * tb_v13955 = "        else if (e.type == ClientMessage && (Atom)e.xclient.data.l[0] == tb_wm_del) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13955; }
    { const char * tb_v13956 = "        else if (e.type == KeyPress || e.type == KeyRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13956; }
    { const char * tb_v13957 = "            int k = tb_x_key(XLookupKeysym(&e.xkey, 0));\n"; *(const char * *)tb_grow(v_lines) = tb_v13957; }
    { const char * tb_v13958 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13958; }
    { const char * tb_v13959 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13959; }
    { const char * tb_v13960 = "                char buf[16]; KeySym ks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13960; }
    { const char * tb_v13961 = "                XLookupString(&e.xkey, buf, sizeof buf, &ks, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13961; }
    { const char * tb_v13962 = "                if (!(e.xkey.state & ControlMask)) tb_type_cp(tb_x_uni(ks));\n"; *(const char * *)tb_grow(v_lines) = tb_v13962; }
    { const char * tb_v13963 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v13963; }
    { const char * tb_v13964 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13964; }
    { const char * tb_v13965 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13965; }
    { const char * tb_v13966 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v13966; }
    { const char * tb_v13967 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13967; }
    { const char * tb_v13968 = "            if (e.type == ButtonPress && e.xbutton.button == 5) tb_wheel_add(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13968; }
    { const char * tb_v13969 = "            tb_mx = e.xbutton.x; tb_my = e.xbutton.y;\n"; *(const char * *)tb_grow(v_lines) = tb_v13969; }
    { const char * tb_v13970 = "        } else if (e.type == MotionNotify) tb_mouse_at(e.xmotion.x, e.xmotion.y);\n"; *(const char * *)tb_grow(v_lines) = tb_v13970; }
    { const char * tb_v13971 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13971; }
    { const char * tb_v13972 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v13972; }
    { const char * tb_v13973 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13973; }
    { const char * tb_v13974 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13974; }
    { const char * tb_v13975 = "    if (tb_wcur != was) tb_wswitch(was);\n"; *(const char * *)tb_grow(v_lines) = tb_v13975; }
    { const char * tb_v13976 = "    if (tb_mlock && tb_mwarp) { XWarpPointer(tb_dpy, None, tb_xw, 0, 0, 0, 0, tb_gw / 2, tb_gh / 2); tb_mwarp = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13976; }
    { const char * tb_v13977 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v13977; }
    { const char * tb_v13978 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13978; }
    { const char * tb_v13979 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v13979; }
    { const char * tb_v13980 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v13980; }
    { const char * tb_v13981 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v13981; }
    { const char * tb_v13982 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v13982; }
    { const char * tb_v13983 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v13983; }
    { const char * tb_v13984 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v13984; }
    { const char * tb_v13985 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13985; }
    { const char * tb_v13986 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13986; }
    { const char * tb_v13987 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13987; }
    { const char * tb_v13988 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13988; }
    { const char * tb_v13989 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13989; }
    { const char * tb_v13990 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v13990; }
    { const char * tb_v13991 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13991; }
    { const char * tb_v13992 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v13992; }
    { const char * tb_v13993 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v13993; }
    { const char * tb_v13994 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v13994; }
    { const char * tb_v13995 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13995; }
    { const char * tb_v13996 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13996; }
    { const char * tb_v13997 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v13997; }
    { const char * tb_v13998 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v13998; }
    { const char * tb_v13999 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v13999; }
    { const char * tb_v14000 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14000; }
    { const char * tb_v14001 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14001; }
    { const char * tb_v14002 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14002; }
    { const char * tb_v14003 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14003; }
    { const char * tb_v14004 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14004; }
    { const char * tb_v14005 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14005; }
    { const char * tb_v14006 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14006; }
    { const char * tb_v14007 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v14007; }
    { const char * tb_v14008 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v14008; }
    { const char * tb_v14009 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14009; }
    { const char * tb_v14010 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14010; }
    { const char * tb_v14011 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14011; }
    { const char * tb_v14012 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14012; }
    { const char * tb_v14013 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14013; }
    { const char * tb_v14014 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14014; }
    { const char * tb_v14015 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14015; }
    { const char * tb_v14016 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14016; }
    { const char * tb_v14017 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14017; }
    { const char * tb_v14018 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14018; }
    { const char * tb_v14019 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14019; }
    { const char * tb_v14020 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14020; }
    { const char * tb_v14021 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14021; }
    { const char * tb_v14022 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v14022; }
    { const char * tb_v14023 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14023; }
    { const char * tb_v14024 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v14024; }
    { const char * tb_v14025 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v14025; }
    { const char * tb_v14026 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14026; }
    { const char * tb_v14027 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14027; }
    { const char * tb_v14028 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14028; }
    { const char * tb_v14029 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14029; }
    { const char * tb_v14030 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v14030; }
    { const char * tb_v14031 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14031; }
    { const char * tb_v14032 = "        fprintf(stderr, tb_tr(\"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\"), diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14032; }
    { const char * tb_v14033 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14033; }
    { const char * tb_v14034 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14034; }
    { const char * tb_v14035 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v14035; }
    { const char * tb_v14036 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v14036; }
    { const char * tb_v14037 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v14037; }
    { const char * tb_v14038 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14038; }
    { const char * tb_v14039 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14039; }
    { const char * tb_v14040 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14040; }
    { const char * tb_v14041 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v14041; }
    { const char * tb_v14042 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v14042; }
    { const char * tb_v14043 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v14043; }
    { const char * tb_v14044 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v14044; }
    { const char * tb_v14045 = "    int used;\n"; *(const char * *)tb_grow(v_lines) = tb_v14045; }
    { const char * tb_v14046 = "    uint32_t *px; int gw, gh, gclosed, mx, my, mdown, mtap, wheel; double wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v14046; }
    { const char * tb_v14047 = "    int mside[2], mside_tap[2], ntyped; char typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v14047; }
    { const char * tb_v14048 = "    unsigned char keys[256], ktap[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v14048; }
    { const char * tb_v14049 = "    int new_w, new_h, resizable, gpu_on, zclr, gzclr; uint32_t *zb; long long zb_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14049; }
    { const char * tb_v14050 = "    TB_WPLAT\n"; *(const char * *)tb_grow(v_lines) = tb_v14050; }
    { const char * tb_v14051 = "} tb_wslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v14051; }
    { const char * tb_v14052 = "static tb_wslot tb_wins[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v14052; }
    { const char * tb_v14053 = "#define TB_WFIELDS(X) X(px, tb_px) X(gw, tb_gw) X(gh, tb_gh) X(gclosed, tb_gclosed) X(mx, tb_mx) X(my, tb_my) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v14053; }
    { const char * tb_v14054 = "    X(mdown, tb_mdown) X(mtap, tb_mtap) X(wheel, tb_wheel) X(wheel_f, tb_wheel_f) X(ntyped, tb_ntyped) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v14054; }
    { const char * tb_v14055 = "    X(new_w, tb_new_w) X(new_h, tb_new_h) X(resizable, tb_resizable) X(gpu_on, tb_gpu_on) X(zclr, tb_zclr) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v14055; }
    { const char * tb_v14056 = "    X(gzclr, tb_gzclr) X(zb, tb_zb) X(zb_n, tb_zb_n)\n"; *(const char * *)tb_grow(v_lines) = tb_v14056; }
    { const char * tb_v14057 = "#define TB_WSAVE1(f, g) s->f = g;\n"; *(const char * *)tb_grow(v_lines) = tb_v14057; }
    { const char * tb_v14058 = "#define TB_WLOAD1(f, g) g = s->f;\n"; *(const char * *)tb_grow(v_lines) = tb_v14058; }
    { const char * tb_v14059 = "static void tb_wsave(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14059; }
    { const char * tb_v14060 = "    TB_WFIELDS(TB_WSAVE1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14060; }
    { const char * tb_v14061 = "    memcpy(s->mside, tb_mside, sizeof s->mside); memcpy(s->mside_tap, tb_mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14061; }
    { const char * tb_v14062 = "    memcpy(s->typed, tb_typed, sizeof s->typed); memcpy(s->keys, tb_keys, sizeof s->keys); memcpy(s->ktap, tb_ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14062; }
    { const char * tb_v14063 = "    TB_WPLAT_SAVE(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v14063; }
    { const char * tb_v14064 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14064; }
    { const char * tb_v14065 = "static void tb_wload(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14065; }
    { const char * tb_v14066 = "    TB_WFIELDS(TB_WLOAD1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14066; }
    { const char * tb_v14067 = "    memcpy(tb_mside, s->mside, sizeof s->mside); memcpy(tb_mside_tap, s->mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14067; }
    { const char * tb_v14068 = "    memcpy(tb_typed, s->typed, sizeof s->typed); memcpy(tb_keys, s->keys, sizeof s->keys); memcpy(tb_ktap, s->ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14068; }
    { const char * tb_v14069 = "    TB_WPLAT_LOAD(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v14069; }
    { const char * tb_v14070 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14070; }
    { const char * tb_v14071 = "TB_API int tb_wfind(uintptr_t h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14071; }
    { const char * tb_v14072 = "    for (int i = 0; i < tb_wn; i++) if (tb_wins[i].used && tb_whand[i] == h && h) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v14072; }
    { const char * tb_v14073 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14073; }
