    { const char * tb_v14236 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14236; }
    { const char * tb_v14237 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v14237; }
    { const char * tb_v14238 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14238; }
    { const char * tb_v14239 = "    if (tb_wn > 1) tb_windows_show();\n"; *(const char * *)tb_grow(v_lines) = tb_v14239; }
    { const char * tb_v14240 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14240; }
    { const char * tb_v14241 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v14241; }
    { const char * tb_v14242 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v14242; }
