    { const char * tb_v14245 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v14245; }
    { const char * tb_v14246 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v14246; }
    { const char * tb_v14247 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14247; }
    { const char * tb_v14248 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14248; }
    { const char * tb_v14249 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14249; }
    { const char * tb_v14250 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v14250; }
    { const char * tb_v14251 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14251; }
    { const char * tb_v14252 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v14252; }
    { const char * tb_v14253 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v14253; }
    { const char * tb_v14254 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v14254; }
    { const char * tb_v14255 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v14255; }
    { const char * tb_v14256 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14256; }
    { const char * tb_v14257 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14257; }
    { const char * tb_v14258 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v14258; }
    { const char * tb_v14259 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v14259; }
    { const char * tb_v14260 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14260; }
    { const char * tb_v14261 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14261; }
    { const char * tb_v14262 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v14262; }
