    { const char * tb_v14275 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14275; }
    { const char * tb_v14276 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c & 0xFFFFFF); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v14276; }
    { const char * tb_v14277 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14277; }
    { const char * tb_v14278 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14278; }
    { const char * tb_v14279 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14279; }
    { const char * tb_v14280 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14280; }
    { const char * tb_v14281 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14281; }
    { const char * tb_v14282 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v14282; }
    { const char * tb_v14283 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14283; }
    { const char * tb_v14284 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14284; }
    { const char * tb_v14285 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb).\n"; *(const char * *)tb_grow(v_lines) = tb_v14285; }
    { const char * tb_v14286 = "// Смешивание как у видеокарты: округл(цвет * a / 255) + округл(фон * (255 - a) / 255), a = 255 − прозрачность;\n"; *(const char * *)tb_grow(v_lines) = tb_v14286; }
    { const char * tb_v14287 = "// в TB_GPU_CHECK — по таблице пробы (tb_blend_lut), тогда кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14287; }
    { const char * tb_v14288 = "TB_INL uint32_t tb_mix_a(uint32_t d, uint32_t c, uint32_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14288; }
    { const char * tb_v14289 = "    if (a >= 255) return c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14289; }
    { const char * tb_v14290 = "    if (a == 0) return d & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14290; }
    { const char * tb_v14291 = "    uint32_t r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14291; }
    { const char * tb_v14292 = "    for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14292; }
    { const char * tb_v14293 = "        uint32_t sc = (c >> sh) & 255, dc = (d >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14293; }
    { const char * tb_v14294 = "        uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14294; }
    { const char * tb_v14295 = "        r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14295; }
    { const char * tb_v14296 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14296; }
    { const char * tb_v14297 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14297; }
    { const char * tb_v14298 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14298; }
    { const char * tb_v14299 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14299; }
    { const char * tb_v14300 = "    return tb_mix_a(d, c, 255 - ((c >> 24) & 255));\n"; *(const char * *)tb_grow(v_lines) = tb_v14300; }
    { const char * tb_v14301 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14301; }
    { const char * tb_v14302 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14302; }
    { const char * tb_v14303 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14303; }
    { const char * tb_v14304 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14304; }
    { const char * tb_v14305 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14305; }
    { const char * tb_v14306 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14306; }
    { const char * tb_v14307 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14307; }
    { const char * tb_v14308 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14308; }
    { const char * tb_v14309 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14309; }
    { const char * tb_v14310 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14310; }
    { const char * tb_v14311 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14311; }
    { const char * tb_v14312 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14312; }
    { const char * tb_v14313 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14313; }
    { const char * tb_v14314 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14314; }
    { const char * tb_v14315 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14315; }
    { const char * tb_v14316 = "// точка (i, j) с прозрачностью a (0..255) цвета c\n"; *(const char * *)tb_grow(v_lines) = tb_v14316; }
    { const char * tb_v14317 = "TB_INL void tb_put_a(long long i, long long j, uint32_t c, uint32_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14317; }
    { const char * tb_v14318 = "    if (i < 0 || j < 0 || i >= tb_gw || j >= tb_gh || a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14318; }
    { const char * tb_v14319 = "    uint32_t *p = &tb_px[j * tb_gw + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14319; }
    { const char * tb_v14320 = "    *p = tb_mix_a(*p, c, a);\n"; *(const char * *)tb_grow(v_lines) = tb_v14320; }
    { const char * tb_v14321 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14321; }
    { const char * tb_v14322 = "// целый корень floor(sqrt(n)) — одинаково на процессоре и в шейдере\n"; *(const char * *)tb_grow(v_lines) = tb_v14322; }
    { const char * tb_v14323 = "TB_INL uint32_t tb_isqrt(uint32_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14323; }
    { const char * tb_v14324 = "    uint32_t s = (uint32_t)sqrt((double)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v14324; }
    { const char * tb_v14325 = "    while (s * s > n) s--;\n"; *(const char * *)tb_grow(v_lines) = tb_v14325; }
    { const char * tb_v14326 = "    while ((s + 1) * (s + 1) <= n) s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14326; }
    { const char * tb_v14327 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14327; }
    { const char * tb_v14328 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14328; }
    { const char * tb_v14329 = "// сглаженный угол: q = (2·dx)² + (2·dy)² от центра угла до середины точки, радиус r ≤ 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v14329; }
    { const char * tb_v14330 = "// Покрытие 0..255 = (r + 0.5 − расстояние), целыми числами (так же считает шейдер)\n"; *(const char * *)tb_grow(v_lines) = tb_v14330; }
    { const char * tb_v14331 = "TB_INL uint32_t tb_round_cov(uint32_t q, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14331; }
    { const char * tb_v14332 = "    long long lo = 2 * r - 1, hi = 2 * r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14332; }
    { const char * tb_v14333 = "    if (lo >= 0 && q <= (uint32_t)(lo * lo)) return 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14333; }
    { const char * tb_v14334 = "    if (q >= (uint32_t)(hi * hi)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14334; }
    { const char * tb_v14335 = "    long long v = (2 * r + 1) * 64 - (long long)tb_isqrt(q * 4096u);   // 128 · (r + 0.5 − расстояние)\n"; *(const char * *)tb_grow(v_lines) = tb_v14335; }
    { const char * tb_v14336 = "    if (v < 0) v = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14336; }
    { const char * tb_v14337 = "    v = (v * 255 + 64) / 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v14337; }
    { const char * tb_v14338 = "    return v > 255 ? 255 : (uint32_t)v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14338; }
    { const char * tb_v14339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14339; }
    { const char * tb_v14340 = "// тень: внутри радиуса r — вся (ca), дальше к r + size сходит на нет по квадрату; r + size ≤ 255\n"; *(const char * *)tb_grow(v_lines) = tb_v14340; }
    { const char * tb_v14341 = "TB_INL uint32_t tb_shadow_a(uint32_t q, long long r, long long size, uint32_t ca) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14341; }
    { const char * tb_v14342 = "    if (q <= (uint32_t)(4 * r * r)) return ca;\n"; *(const char * *)tb_grow(v_lines) = tb_v14342; }
    { const char * tb_v14343 = "    if (q >= (uint32_t)(4 * (r + size) * (r + size))) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14343; }
    { const char * tb_v14344 = "    long long g = ((r + size) * 128 - (long long)tb_isqrt(q * 4096u)) >> 3;   // осталось до края, в 1/16 точки\n"; *(const char * *)tb_grow(v_lines) = tb_v14344; }
    { const char * tb_v14345 = "    uint32_t S = (uint32_t)(size * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14345; }
    { const char * tb_v14346 = "    if (g < 0) g = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14346; }
    { const char * tb_v14347 = "    if (g > (long long)S) g = S;\n"; *(const char * *)tb_grow(v_lines) = tb_v14347; }
    { const char * tb_v14348 = "    return (ca * (uint32_t)g * (uint32_t)g + S * S / 2) / (S * S);\n"; *(const char * *)tb_grow(v_lines) = tb_v14348; }
    { const char * tb_v14349 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14349; }
    { const char * tb_v14350 = "// угол-квадрат x0..x1, y0..y1 с центром (ox, oy): сглаженный (shadow = 0) или угол тени\n"; *(const char * *)tb_grow(v_lines) = tb_v14350; }
    { const char * tb_v14351 = "TB_API void tb_soft_corner(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, long long r, long long size, long long c, int shadow) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14351; }
    { const char * tb_v14352 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14352; }
