    { const char * tb_v14365 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v14365; }
    { const char * tb_v14366 = "// снаружи к size точкам сходит на нет. Точки делятся на куски без наложений: середина — сплошняком,\n"; *(const char * *)tb_grow(v_lines) = tb_v14366; }
    { const char * tb_v14367 = "// полосы вдоль сторон — по строке/столбцу одной прозрачности, углы — по кругу (tb_soft_corner).\n"; *(const char * *)tb_grow(v_lines) = tb_v14367; }
    { const char * tb_v14368 = "// Всё целыми числами, поэтому видеокарта рисует то же самое точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14368; }
    { const char * tb_v14369 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14369; }
    { const char * tb_v14370 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14370; }
    { const char * tb_v14371 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14371; }
    { const char * tb_v14372 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14372; }
    { const char * tb_v14373 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14373; }
    { const char * tb_v14374 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14374; }
    { const char * tb_v14375 = "    if (r > 127) r = 127;\n"; *(const char * *)tb_grow(v_lines) = tb_v14375; }
    { const char * tb_v14376 = "    if (size > 255 - r) size = 255 - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14376; }
    { const char * tb_v14377 = "    uint32_t ca = 255 - (((uint32_t)c >> 24) & 255), rgb = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v14377; }
    { const char * tb_v14378 = "    // середина\n"; *(const char * *)tb_grow(v_lines) = tb_v14378; }
    { const char * tb_v14379 = "    tb_draw_rect(x, y + r, w, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14379; }
    { const char * tb_v14380 = "    tb_draw_rect(x + r, y, w - 2 * r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14380; }
