    { const char * tb_v14382 = "    // полосы вдоль сторон: k-я строка/столбец от края\n"; *(const char * *)tb_grow(v_lines) = tb_v14382; }
    { const char * tb_v14383 = "    for (long long k = 0; k < size; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14383; }
    { const char * tb_v14384 = "        uint32_t q = (uint32_t)((2 * k + 1) * (2 * k + 1)), a = tb_shadow_a(q, 0, size, ca);\n"; *(const char * *)tb_grow(v_lines) = tb_v14384; }
