    { const char * tb_v14388 = "        tb_draw_rect(x + r, y + h + k, w - 2 * r, 1, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14388; }
    { const char * tb_v14389 = "        tb_draw_rect(x - 1 - k, y + r, 1, h - 2 * r, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14389; }
    { const char * tb_v14390 = "        tb_draw_rect(x + w + k, y + r, 1, h - 2 * r, cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14390; }
    { const char * tb_v14391 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14391; }
    { const char * tb_v14392 = "    // углы\n"; *(const char * *)tb_grow(v_lines) = tb_v14392; }
    { const char * tb_v14393 = "    tb_soft_corner(x - size, y - size, x + r, y + r, x + r, y + r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14393; }
    { const char * tb_v14394 = "    tb_soft_corner(x + w - r, y - size, x + w + size, y + r, x + w - r, y + r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14394; }
    { const char * tb_v14395 = "    tb_soft_corner(x - size, y + h - r, x + r, y + h + size, x + r, y + h - r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14395; }
    { const char * tb_v14396 = "    tb_soft_corner(x + w - r, y + h - r, x + w + size, y + h + size, x + w - r, y + h - r, r, size, c, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14396; }
    { const char * tb_v14397 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14397; }
    { const char * tb_v14398 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v14398; }
    { const char * tb_v14399 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14399; }
    { const char * tb_v14400 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14400; }
    { const char * tb_v14401 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14401; }
    { const char * tb_v14402 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v14402; }
    { const char * tb_v14403 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v14403; }
    { const char * tb_v14404 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14404; }
    { const char * tb_v14405 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14405; }
    { const char * tb_v14406 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14406; }
    { const char * tb_v14407 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14407; }
    { const char * tb_v14408 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14408; }
    { const char * tb_v14409 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14409; }
    { const char * tb_v14410 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v14410; }
    { const char * tb_v14411 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14411; }
    { const char * tb_v14412 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v14412; }
    { const char * tb_v14413 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14413; }
    { const char * tb_v14414 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba).\n"; *(const char * *)tb_grow(v_lines) = tb_v14414; }
    { const char * tb_v14415 = "// Куски без наложений: середина и боковые полосы — прямоугольники, углы — сглаженные квадраты r×r\n"; *(const char * *)tb_grow(v_lines) = tb_v14415; }
    { const char * tb_v14416 = "// (tb_soft_corner): процессор и видеокарта считают покрытие одной целой формулой\n"; *(const char * *)tb_grow(v_lines) = tb_v14416; }
    { const char * tb_v14417 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14417; }
    { const char * tb_v14418 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14418; }
    { const char * tb_v14419 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14419; }
    { const char * tb_v14420 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v14420; }
    { const char * tb_v14421 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14421; }
