    { const char * tb_v14428 = "    tb_draw_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14428; }
    { const char * tb_v14429 = "    long long cx[4] = { x, x + w - r, x, x + w - r }, cy[4] = { y, y, y + h - r, y + h - r };\n"; *(const char * *)tb_grow(v_lines) = tb_v14429; }
    { const char * tb_v14430 = "    long long ox[4] = { x + r, x + w - r, x + r, x + w - r }, oy[4] = { y + r, y + r, y + h - r, y + h - r };\n"; *(const char * *)tb_grow(v_lines) = tb_v14430; }
    { const char * tb_v14431 = "    for (int k = 0; k < 4; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14431; }
    { const char * tb_v14432 = "        if (m & (1 << k)) tb_soft_corner(cx[k], cy[k], cx[k] + r, cy[k] + r, ox[k], oy[k], r, 0, c, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v14432; }
    { const char * tb_v14433 = "        else tb_draw_rect(cx[k], cy[k], r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14433; }
    { const char * tb_v14434 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14434; }
    { const char * tb_v14435 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14435; }
    { const char * tb_v14436 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v14436; }
    { const char * tb_v14437 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14437; }
    { const char * tb_v14438 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14438; }
    { const char * tb_v14439 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v14439; }
    { const char * tb_v14440 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14440; }
    { const char * tb_v14441 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v14441; }
    { const char * tb_v14442 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14442; }
    { const char * tb_v14443 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v14443; }
    { const char * tb_v14444 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14444; }
    { const char * tb_v14445 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14445; }
    { const char * tb_v14446 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14446; }
    { const char * tb_v14447 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v14447; }
    { const char * tb_v14448 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v14448; }
    { const char * tb_v14449 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14449; }
    { const char * tb_v14450 = "        sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14450; }
    { const char * tb_v14451 = "        sg += (long long)((in >> 8) & 255) - ((out >> 8) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14451; }
    { const char * tb_v14452 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v14452; }
    { const char * tb_v14453 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14453; }
    { const char * tb_v14454 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14454; }
    { const char * tb_v14455 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v14455; }
    { const char * tb_v14456 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v14456; }
    { const char * tb_v14457 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14457; }
    { const char * tb_v14458 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14458; }
    { const char * tb_v14459 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14459; }
    { const char * tb_v14460 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14460; }
    { const char * tb_v14461 = "    long long W = x1 - x0, H = y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14461; }
    { const char * tb_v14462 = "    if (W <= 1 || H <= 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14462; }
    { const char * tb_v14463 = "    int half = r >= 4 && W >= 8 && H >= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14463; }
    { const char * tb_v14464 = "    long long bw = half ? (W + 1) / 2 : W, bh = half ? (H + 1) / 2 : H, br = half ? r / 2 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14464; }
    { const char * tb_v14465 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14465; }
    { const char * tb_v14466 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14466; }
    { const char * tb_v14467 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v14467; }
    { const char * tb_v14468 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v14468; }
    { const char * tb_v14469 = "        for (long long yy = 0; yy < bh; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14469; }
    { const char * tb_v14470 = "            for (long long xx = 0; xx < bw; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14470; }
    { const char * tb_v14471 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14471; }
    { const char * tb_v14472 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14472; }
    { const char * tb_v14473 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v14473; }
    { const char * tb_v14474 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v14474; }
    { const char * tb_v14475 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14475; }
    { const char * tb_v14476 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14476; }
    { const char * tb_v14477 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v14477; }
