    { const char * tb_v14571 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14571; }
    { const char * tb_v14572 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14572; }
