    { const char * tb_v14576 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14576; }
    { const char * tb_v14577 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v14577; }
