    { const char * tb_v14582 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v14582; }
    { const char * tb_v14583 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14583; }
    { const char * tb_v14584 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v14584; }
