    { const char * tb_v14587 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14587; }
    { const char * tb_v14588 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14588; }
    { const char * tb_v14589 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14589; }
