    { const char * tb_v14745 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v14745; }
    { const char * tb_v14746 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14746; }
    { const char * tb_v14747 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14747; }
    { const char * tb_v14748 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v14748; }
    { const char * tb_v14749 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v14749; }
    { const char * tb_v14750 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v14750; }
    { const char * tb_v14751 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v14751; }
    { const char * tb_v14752 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v14752; }
    { const char * tb_v14753 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v14753; }
    { const char * tb_v14754 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v14754; }
    { const char * tb_v14755 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v14755; }
    { const char * tb_v14756 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v14756; }
    { const char * tb_v14757 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v14757; }
    { const char * tb_v14758 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v14758; }
    { const char * tb_v14759 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v14759; }
    { const char * tb_v14760 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v14760; }
    { const char * tb_v14761 = "typedef struct { int parent, useq; double piv[3], rot[3], mv[3], q[4]; } tb_bone_t;   // кость: родитель, сустав, поворот (или кватернион q, useq), сдвиг\n"; *(const char * *)tb_grow(v_lines) = tb_v14761; }
    { const char * tb_v14762 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v14762; }
    { const char * tb_v14763 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v14763; }
    { const char * tb_v14764 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v14764; }
    { const char * tb_v14765 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v14765; }
    { const char * tb_v14766 = "    long long nch, *chr; double *chs, bs[4]; int chok;\n"; *(const char * *)tb_grow(v_lines) = tb_v14766; }
    { const char * tb_v14767 = "    int smooth, alpha, cnok; double shine, glow; double *cn; long long cncap;   // плавный свет, прозрачность 0…255, блеск, свечение; нормали в углах\n"; *(const char * *)tb_grow(v_lines) = tb_v14767; }
    { const char * tb_v14768 = "    tb_bone_t *bones; long long nb, capb; int16_t *sb; float *sw;\n"; *(const char * *)tb_grow(v_lines) = tb_v14768; }
    { const char * tb_v14769 = "    int shp, shc, shok; float shv[16]; int shimg[4]; int noshadow; float *shvd; long long shvn, shvcap, shused; void *shvb;\n"; *(const char * *)tb_grow(v_lines) = tb_v14769; }
    { const char * tb_v14770 = "    long long lod; double lodd, far, ub[4]; int hasub; } tb_mesh;   // lod — сетка вместо этой дальше lodd; far — дальше не рисовать; ub — свой шар (mesh_bounds)   // gpu func: шейдер точки и углов (-1 — обычный), настройки, углы для видеокарты     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v14770; }
    { const char * tb_v14771 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14771; }
    { const char * tb_v14772 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14772; }
    { const char * tb_v14773 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v14773; }
    { const char * tb_v14774 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v14774; }
    { const char * tb_v14775 = "TB_API long long *tb_mfree = 0, tb_nmfree = 0, tb_capmfree = 0;   // номера сеток после mesh_free: mesh_new берёт их снова\n"; *(const char * *)tb_grow(v_lines) = tb_v14775; }
    { const char * tb_v14776 = "static void tb_mesh_reset(long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14776; }
    { const char * tb_v14777 = "    memset(&tb_meshes[i], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14777; }
    { const char * tb_v14778 = "    tb_meshes[i].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14778; }
