    { const char * tb_v14783 = "    tb_meshes[i].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14783; }
    { const char * tb_v14784 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14784; }
    { const char * tb_v14785 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14785; }
    { const char * tb_v14786 = "    if (tb_nmfree > 0) { long long i = tb_mfree[--tb_nmfree]; tb_mesh_reset(i); return i; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14786; }
    { const char * tb_v14787 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14787; }
    { const char * tb_v14788 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14788; }
    { const char * tb_v14789 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14789; }
    { const char * tb_v14790 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14790; }
    { const char * tb_v14791 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v14791; }
    { const char * tb_v14792 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14792; }
    { const char * tb_v14793 = "    tb_meshes[tb_nmesh].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14793; }
    { const char * tb_v14794 = "    tb_meshes[tb_nmesh].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14794; }
    { const char * tb_v14795 = "    tb_meshes[tb_nmesh].shp = tb_meshes[tb_nmesh].shc = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14795; }
    { const char * tb_v14796 = "    tb_meshes[tb_nmesh].shused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14796; }
    { const char * tb_v14797 = "    tb_meshes[tb_nmesh].lod = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14797; }
    { const char * tb_v14798 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14798; }
    { const char * tb_v14799 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14799; }
    { const char * tb_v14800 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14800; }
    { const char * tb_v14801 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14801; }
    { const char * tb_v14802 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14802; }
    { const char * tb_v14803 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14803; }
    { const char * tb_v14804 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14804; }
    { const char * tb_v14805 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14805; }
    { const char * tb_v14806 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v14806; }
    { const char * tb_v14807 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14807; }
    { const char * tb_v14808 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v14808; }
    { const char * tb_v14809 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14809; }
    { const char * tb_v14810 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v14810; }
    { const char * tb_v14811 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v14811; }
    { const char * tb_v14812 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14812; }
    { const char * tb_v14813 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14813; }
    { const char * tb_v14814 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14814; }
    { const char * tb_v14815 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14815; }
    { const char * tb_v14816 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14816; }
    { const char * tb_v14817 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14817; }
    { const char * tb_v14818 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v14818; }
    { const char * tb_v14819 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14819; }
    { const char * tb_v14820 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14820; }
    { const char * tb_v14821 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14821; }
    { const char * tb_v14822 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v14822; }
    { const char * tb_v14823 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14823; }
    { const char * tb_v14824 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14824; }
    { const char * tb_v14825 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14825; }
