    { const char * tb_v14827 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14827; }
    { const char * tb_v14828 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14828; }
    { const char * tb_v14829 = "        if (m->sb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14829; }
    { const char * tb_v14830 = "            m->sb = (int16_t *)realloc(m->sb, sizeof(int16_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14830; }
    { const char * tb_v14831 = "            m->sw = (float *)realloc(m->sw, sizeof(float) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14831; }
    { const char * tb_v14832 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14832; }
    { const char * tb_v14833 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14833; }
    { const char * tb_v14834 = "    if (m->sb) for (int i = 0; i < 4; i++) { m->sb[4 * m->nv + i] = -1; m->sw[4 * m->nv + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14834; }
    { const char * tb_v14835 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v14835; }
    { const char * tb_v14836 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14836; }
    { const char * tb_v14837 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14837; }
    { const char * tb_v14838 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14838; }
    { const char * tb_v14839 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v14839; }
    { const char * tb_v14840 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v14840; }
