    { const char * tb_v14844 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14844; }
    { const char * tb_v14845 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14845; }
    { const char * tb_v14846 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v14846; }
    { const char * tb_v14847 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14847; }
    { const char * tb_v14848 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14848; }
    { const char * tb_v14849 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14849; }
    { const char * tb_v14850 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v14850; }
    { const char * tb_v14851 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v14851; }
