    { const char * tb_v14853 = "    if (m->shp < 0 && m->shc < 0) tb_mesh_gdirty = 1;   // со своим шейдером — общий буфер сеток не трогаем\n"; *(const char * *)tb_grow(v_lines) = tb_v14853; }
    { const char * tb_v14854 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14854; }
    { const char * tb_v14855 = "    m->chok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14855; }
