    { const char * tb_v14857 = "    m->cnok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14857; }
    { const char * tb_v14858 = "    m->shok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14858; }
    { const char * tb_v14859 = "    if (m->n == m->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14859; }
    { const char * tb_v14860 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14860; }
