    { const char * tb_v14862 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14862; }
    { const char * tb_v14863 = "        if (m->uv) m->uv = (double *)realloc(m->uv, sizeof(double) * 6 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v14863; }
