    { const char * tb_v14894 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14894; }
    { const char * tb_v14895 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14895; }
    { const char * tb_v14896 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v14896; }
