    { const char * tb_v14904 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v14904; }
    { const char * tb_v14905 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14905; }
    { const char * tb_v14906 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14906; }
    { const char * tb_v14907 = "// ---- свет: одно солнце (направление к нему) и фон; яркость грани — от того, как она повёрнута к солнцу ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14907; }
    { const char * tb_v14908 = "// Всё в целых, одной формулой на процессоре и на видеокарте (tb3.vert, tb3.metal): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v14908; }
    { const char * tb_v14909 = "TB_API double tb_lt[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v14909; }
    { const char * tb_v14910 = "TB_API int tb_lamb = -1;   // фон × 256; -1 — света нет, цвета как есть\n"; *(const char * *)tb_grow(v_lines) = tb_v14910; }
    { const char * tb_v14911 = "TB_API double tb_amb0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14911; }
    { const char * tb_v14912 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14912; }
    { const char * tb_v14913 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14913; }
    { const char * tb_v14914 = "    double l = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v14914; }
    { const char * tb_v14915 = "    // light(0, 0, 0, ...) — выключить солнце; фон остаётся для ламп (point_light, spot_light)\n"; *(const char * *)tb_grow(v_lines) = tb_v14915; }
    { const char * tb_v14916 = "    if (!(l > 1e-12)) { tb_lamb = -1; tb_amb0 = amb > 0 ? (amb < 1 ? amb : 1) : 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14916; }
    { const char * tb_v14917 = "    tb_lt[0] = dx / l; tb_lt[1] = dy / l; tb_lt[2] = dz / l;\n"; *(const char * *)tb_grow(v_lines) = tb_v14917; }
