    { const char * tb_v14921 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14921; }
    { const char * tb_v14922 = "// нормали треугольников: (b - a) × (c - a), длина 2^14. У куба, где грани по кругу против часовой\n"; *(const char * *)tb_grow(v_lines) = tb_v14922; }
    { const char * tb_v14923 = "// стрелки снаружи, нормаль смотрит наружу\n"; *(const char * *)tb_grow(v_lines) = tb_v14923; }
    { const char * tb_v14924 = "static void tb_mesh_normals(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14924; }
    { const char * tb_v14925 = "    if (m->nrmok) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14925; }
    { const char * tb_v14926 = "    m->nrmok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14926; }
    { const char * tb_v14927 = "    if (m->nrmcap < m->n) { m->nrmcap = m->cap; m->nrm = (int32_t *)realloc(m->nrm, sizeof(int32_t) * 3 * (size_t)m->nrmcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14927; }
    { const char * tb_v14928 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14928; }
    { const char * tb_v14929 = "        const double *a = m->v + 3 * m->t[3 * t], *b = m->v + 3 * m->t[3 * t + 1], *c = m->v + 3 * m->t[3 * t + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14929; }
    { const char * tb_v14930 = "        double e1[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, e2[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v14930; }
    { const char * tb_v14931 = "        double n[3] = { e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v14931; }
    { const char * tb_v14932 = "        double l = sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14932; }
    { const char * tb_v14933 = "        for (int k = 0; k < 3; k++) m->nrm[3 * t + k] = l > 1e-300 ? (int32_t)tb_rnd(n[k] / l * 16384) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14933; }
    { const char * tb_v14934 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14934; }
    { const char * tb_v14935 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14935; }
    { const char * tb_v14936 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v14936; }
    { const char * tb_v14937 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v14937; }
    { const char * tb_v14938 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14938; }
    { const char * tb_v14939 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14939; }
    { const char * tb_v14940 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14940; }
    { const char * tb_v14941 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14941; }
    { const char * tb_v14942 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14942; }
    { const char * tb_v14943 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v14943; }
    { const char * tb_v14944 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14944; }
    { const char * tb_v14945 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14945; }
    { const char * tb_v14946 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14946; }
    { const char * tb_v14947 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14947; }
    { const char * tb_v14948 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14948; }
    { const char * tb_v14949 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14949; }
    { const char * tb_v14950 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14950; }
    { const char * tb_v14951 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v14951; }
    { const char * tb_v14952 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v14952; }
    { const char * tb_v14953 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v14953; }
    { const char * tb_v14954 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v14954; }
    { const char * tb_v14955 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14955; }
    { const char * tb_v14956 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14956; }
    { const char * tb_v14957 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14957; }
    { const char * tb_v14958 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v14958; }
    { const char * tb_v14959 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14959; }
    { const char * tb_v14960 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v14960; }
    { const char * tb_v14961 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14961; }
    { const char * tb_v14962 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14962; }
    { const char * tb_v14963 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14963; }
    { const char * tb_v14964 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v14964; }
    { const char * tb_v14965 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v14965; }
    { const char * tb_v14966 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14966; }
    { const char * tb_v14967 = "TB_API long long tb_3vcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14967; }
    { const char * tb_v14968 = "// старый путь (дроби): сетка задевает камеру или край, где целые не годятся — обрезка у камеры и рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v14968; }
    { const char * tb_v14969 = "TB_API long long *tb_3vst = 0, tb_3vgen = 0;   // какой угол уже посчитан в этом вызове\n"; *(const char * *)tb_grow(v_lines) = tb_v14969; }
    { const char * tb_v14970 = "// ---- картинка на сетке: плоскости u·W и v·W по трём углам ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14970; }
    { const char * tb_v14971 = "// треугольник t сетки рисуется картинкой? (есть картинка, у треугольника есть (u, v), видеокарта умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v14971; }
    { const char * tb_v14972 = "TB_INL int tb_tex_on(const tb_mesh *m, long long t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14972; }
    { const char * tb_v14973 = "    return m->tex >= 0 && m->uv && !__builtin_isnan(m->uv[6 * t]) && (!tb_gpu_on || tb_gpu_tex);\n"; *(const char * *)tb_grow(v_lines) = tb_v14973; }
    { const char * tb_v14974 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14974; }
    { const char * tb_v14975 = "// (u, v) угла в 1/16 точки картинки, не дальше ±2^19 (чтобы плоскости влезли в 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v14975; }
    { const char * tb_v14976 = "TB_INL long long tb_tex_q(double u, int w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14976; }
    { const char * tb_v14977 = "    double q = u * w * 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14977; }
    { const char * tb_v14978 = "    if (!(q > -524288)) q = -524288;   // и NaN\n"; *(const char * *)tb_grow(v_lines) = tb_v14978; }
    { const char * tb_v14979 = "    if (q > 524288) q = 524288;\n"; *(const char * *)tb_grow(v_lines) = tb_v14979; }
    { const char * tb_v14980 = "    return tb_rnd(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v14980; }
    { const char * tb_v14981 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14981; }
    { const char * tb_v14982 = "// плоскость S по трём углам в целых: та же формула, что у плоскости глубины в tb_m3_tri\n"; *(const char * *)tb_grow(v_lines) = tb_v14982; }
    { const char * tb_v14983 = "static void tb_tex_plane_i(const long long *a, const long long *b, const long long *c, const long long *S, int64_t *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14983; }
    { const char * tb_v14984 = "    long long s0 = S[0], s1 = S[1], s2 = S[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14984; }
    { const char * tb_v14985 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14985; }
    { const char * tb_v14986 = "    if (area < 0) { const long long *k = b; b = c; c = k; long long ks = s1; s1 = s2; s2 = ks; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14986; }
    { const char * tb_v14987 = "    if (area == 0) { o[0] = o[1] = 0; o[2] = 64 * s0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14987; }
    { const char * tb_v14988 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = s1 - s0, d2 = s2 - s0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14988; }
    { const char * tb_v14989 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v14989; }
