    { const char * tb_v15124 = "        tb_poly_draw(sx, sy, n, tb_shade(m->c[t], m->nrm + 3 * t, L, (sx[1] - sx[0]) * (sy[2] - sy[0]) - (sy[1] - sy[0]) * (sx[2] - sx[0]) > 0), pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v15124; }
