    { const char * tb_v15128 = "// ---- 3D в целых числах: так же считает видеокарта (compiler/gpu/tb3.vert, tb.metal) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v15128; }
    { const char * tb_v15129 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v15129; }
    { const char * tb_v15130 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15130; }
    { const char * tb_v15131 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v15131; }
    { const char * tb_v15132 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v15132; }
    { const char * tb_v15133 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15133; }
    { const char * tb_v15134 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v15134; }
    { const char * tb_v15135 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v15135; }
    { const char * tb_v15136 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v15136; }
    { const char * tb_v15137 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15137; }
    { const char * tb_v15138 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v15138; }
    { const char * tb_v15139 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v15139; }
    { const char * tb_v15140 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v15140; }
    { const char * tb_v15141 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v15141; }
    { const char * tb_v15142 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v15142; }
    { const char * tb_v15143 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v15143; }
    { const char * tb_v15144 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15144; }
    { const char * tb_v15145 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v15145; }
    { const char * tb_v15146 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v15146; }
    { const char * tb_v15147 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15147; }
    { const char * tb_v15148 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v15148; }
    { const char * tb_v15149 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15149; }
    { const char * tb_v15150 = "    int ret = area > 0 ? 1 : 2;   // 1 — грань смотрит на нас, 2 — спиной\n"; *(const char * *)tb_grow(v_lines) = tb_v15150; }
    { const char * tb_v15151 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v15151; }
    { const char * tb_v15152 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v15152; }
    { const char * tb_v15153 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v15153; }
    { const char * tb_v15154 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v15154; }
    { const char * tb_v15155 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v15155; }
    { const char * tb_v15156 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v15156; }
    { const char * tb_v15157 = "    return ret;\n"; *(const char * *)tb_grow(v_lines) = tb_v15157; }
    { const char * tb_v15158 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15158; }
    { const char * tb_v15159 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v15159; }
    { const char * tb_v15160 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v15160; }
    { const char * tb_v15161 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v15161; }
    { const char * tb_v15162 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15162; }
    { const char * tb_v15163 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v15163; }
    { const char * tb_v15164 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v15164; }
    { const char * tb_v15165 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15165; }
    { const char * tb_v15166 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15166; }
    { const char * tb_v15167 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v15167; }
    { const char * tb_v15168 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15168; }
    { const char * tb_v15169 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v15169; }
    { const char * tb_v15170 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v15170; }
    { const char * tb_v15171 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15171; }
    { const char * tb_v15172 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15172; }
    { const char * tb_v15173 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v15173; }
    { const char * tb_v15174 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v15174; }
    { const char * tb_v15175 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v15175; }
    { const char * tb_v15176 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v15176; }
    { const char * tb_v15177 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v15177; }
    { const char * tb_v15178 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v15178; }
    { const char * tb_v15179 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15179; }
    { const char * tb_v15180 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15180; }
    { const char * tb_v15181 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v15181; }
    { const char * tb_v15182 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v15182; }
    { const char * tb_v15183 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15183; }
    { const char * tb_v15184 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v15184; }
    { const char * tb_v15185 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v15185; }
    { const char * tb_v15186 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15186; }
    { const char * tb_v15187 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v15187; }
    { const char * tb_v15188 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15188; }
    { const char * tb_v15189 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v15189; }
    { const char * tb_v15190 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v15190; }
    { const char * tb_v15191 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15191; }
    { const char * tb_v15192 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15192; }
    { const char * tb_v15193 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15193; }
    { const char * tb_v15194 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v15194; }
    { const char * tb_v15195 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v15195; }
    { const char * tb_v15196 = "        if (m->shp >= 0 || m->shc >= 0) { m->gt = at; continue; }   // сетка со своим шейдером — в своём буфере углов\n"; *(const char * *)tb_grow(v_lines) = tb_v15196; }
    { const char * tb_v15197 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15197; }
    { const char * tb_v15198 = "            tb_mesh_normals(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v15198; }
    { const char * tb_v15199 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v15199; }
    { const char * tb_v15200 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15200; }
    { const char * tb_v15201 = "                int32_t *o = dst + 4 * (m->gt + 2 * t);\n"; *(const char * *)tb_grow(v_lines) = tb_v15201; }
    { const char * tb_v15202 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v15202; }
    { const char * tb_v15203 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v15203; }
    { const char * tb_v15204 = "                for (int k = 0; k < 3; k++) o[4 + k] = m->nrm[3 * t + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v15204; }
    { const char * tb_v15205 = "                o[7] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15205; }
    { const char * tb_v15206 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v15206; }
    { const char * tb_v15207 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v15207; }
    { const char * tb_v15208 = "        at += m->nv + 2 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v15208; }
    { const char * tb_v15209 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v15209; }
    { const char * tb_v15210 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v15210; }
    { const char * tb_v15211 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15211; }
    { const char * tb_v15212 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15212; }
    { const char * tb_v15213 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v15213; }
    { const char * tb_v15214 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v15214; }
    { const char * tb_v15215 = "    pc->tbase = (int32_t)(m->gt + 2 * g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v15215; }
    { const char * tb_v15216 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15216; }
    { const char * tb_v15217 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15217; }
    { const char * tb_v15218 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v15218; }
    { const char * tb_v15219 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15219; }
    { const char * tb_v15220 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v15220; }
    { const char * tb_v15221 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v15221; }
    { const char * tb_v15222 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15222; }
    { const char * tb_v15223 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v15223; }
    { const char * tb_v15224 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v15224; }
    { const char * tb_v15225 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15225; }
    { const char * tb_v15226 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v15226; }
    { const char * tb_v15227 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15227; }
    { const char * tb_v15228 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15228; }
    { const char * tb_v15229 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v15229; }
    { const char * tb_v15230 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v15230; }
    { const char * tb_v15231 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v15231; }
    { const char * tb_v15232 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v15232; }
    { const char * tb_v15233 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v15233; }
    { const char * tb_v15234 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15234; }
    { const char * tb_v15235 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v15235; }
    { const char * tb_v15236 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v15236; }
    { const char * tb_v15237 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v15237; }
    { const char * tb_v15238 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15238; }
    { const char * tb_v15239 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v15239; }
    { const char * tb_v15240 = "    int texm = m->tex >= 0 && m->uv && (!tb_gpu_on || tb_gpu_tex);   // сетка с картинкой: углы считает процессор\n"; *(const char * *)tb_grow(v_lines) = tb_v15240; }
    { const char * tb_v15241 = "    if (tb_gpu_on && tb_gpu_mesh && !texm) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v15241; }
