    { const char * tb_v16515 = "            for (int k = 0; k < 3; k++) { o[k] = (float)p[k]; o[3 + k] = (float)n[k]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16515; }
    { const char * tb_v16516 = "            o[6] = ((c >> 16) & 255) / 255.0f; o[7] = ((c >> 8) & 255) / 255.0f; o[8] = (c & 255) / 255.0f; o[9] = m->alpha / 255.0f;\n"; *(const char * *)tb_grow(v_lines) = tb_v16516; }
