    { const char * tb_v16521 = "        const double *p0 = m->v + 3 * m->t[3 * t], *p1 = m->v + 3 * m->t[3 * t + 1], *p2 = m->v + 3 * m->t[3 * t + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16521; }
