    { const char * tb_v16574 = "        for (int k = 0; k < 3; k++) { r[195 + k] = (float)tb_smC[k]; r[198 + k] = (float)tb_smR[k]; r[201 + k] = (float)tb_smU[k]; r[204 + k] = (float)tb_smF[k]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16574; }
