    { const char * tb_v16599 = "// ---- процессор: те же шейдеры (функции C от компилятора), треугольники дробными числами ----\n"; *(const char * *)tb_grow(v_lines) = tb_v16599; }
    { const char * tb_v16600 = "typedef struct { double c[3]; float a[15]; } tb_shc_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v16600; }
    { const char * tb_v16601 = "static int tb_sh_nowrite = 0;   // прозрачная сетка (mesh_alpha < 1): глубину не пишет   // угол перед камерой: место у камеры; мир 3, нормаль 3, цвет 4, uv 2, касательная 3\n"; *(const char * *)tb_grow(v_lines) = tb_v16601; }
    { const char * tb_v16602 = "static void tb_sh_px(const tb_shc_t *q, int ps, const float *rec) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16602; }
    { const char * tb_v16603 = "    double f = tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180), hw = tb_gw / 2.0, hh = tb_gh / 2.0, zn = 205.0 / 4096;\n"; *(const char * *)tb_grow(v_lines) = tb_v16603; }
    { const char * tb_v16604 = "    double sx[3], sy[3], iz[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v16604; }
    { const char * tb_v16605 = "    for (int i = 0; i < 3; i++) { iz[i] = 1 / q[i].c[2]; sx[i] = hw + f * q[i].c[0] * iz[i]; sy[i] = hh - f * q[i].c[1] * iz[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16605; }
    { const char * tb_v16606 = "    double area = (sx[1] - sx[0]) * (sy[2] - sy[0]) - (sy[1] - sy[0]) * (sx[2] - sx[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16606; }
    { const char * tb_v16607 = "    if (!(fabs(area) > 1e-12)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v16607; }
    { const char * tb_v16608 = "    double x0 = sx[0], x1 = sx[0], y0 = sy[0], y1 = sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v16608; }
    { const char * tb_v16609 = "    for (int i = 1; i < 3; i++) { x0 = tb_fmin(x0, sx[i]); x1 = tb_fmax(x1, sx[i]); y0 = tb_fmin(y0, sy[i]); y1 = tb_fmax(y1, sy[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v16609; }
    { const char * tb_v16610 = "    long long px0 = (long long)floor(x0), px1 = (long long)ceil(x1), py0 = (long long)floor(y0), py1 = (long long)ceil(y1);\n"; *(const char * *)tb_grow(v_lines) = tb_v16610; }
    { const char * tb_v16611 = "    if (px0 < 0) px0 = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16611; }
    { const char * tb_v16612 = "    if (py0 < 0) py0 = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16612; }
    { const char * tb_v16613 = "    if (px1 > tb_gw - 1) px1 = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16613; }
    { const char * tb_v16614 = "    if (py1 > tb_gh - 1) py1 = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16614; }
    { const char * tb_v16615 = "    tb_shfn pf = tb_shaders[ps].fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v16615; }
    { const char * tb_v16616 = "    float io[48];\n"; *(const char * *)tb_grow(v_lines) = tb_v16616; }
    { const char * tb_v16617 = "    for (long long py = py0; py <= py1; py++) for (long long px = px0; px <= px1; px++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16617; }
    { const char * tb_v16618 = "        double X = px + 0.5, Y = py + 0.5, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v16618; }
    { const char * tb_v16619 = "        for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16619; }
    { const char * tb_v16620 = "            int a = (i + 1) % 3, b = (i + 2) % 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v16620; }
