    { const char * tb_v16632 = "        for (int k = 0; k < 15; k++) A[k] = (float)(l[0] * q[0].a[k] + l[1] * q[1].a[k] + l[2] * q[2].a[k]);\n"; *(const char * *)tb_grow(v_lines) = tb_v16632; }
