    { const char * tb_v16642 = "        for (int k = 0; k < 3; k++) io[20 + k] = rec[12 + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16642; }
    { const char * tb_v16643 = "        for (int k = 0; k < 3; k++) io[23 + k] = A[12 + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16643; }
    { const char * tb_v16644 = "        for (int k = 0; k < 8; k++) io[26 + k] = rec[32 + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16644; }
    { const char * tb_v16645 = "        pf(rec, tb_imgpx, tb_shm, io);\n"; *(const char * *)tb_grow(v_lines) = tb_v16645; }
    { const char * tb_v16646 = "        float al = io[14] > 0 ? (io[14] < 1 ? io[14] : 1) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16646; }
    { const char * tb_v16647 = "        if (al <= 0) continue;   // p.a = 0: точки нет\n"; *(const char * *)tb_grow(v_lines) = tb_v16647; }
