    { const char * tb_v16649 = "        for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16649; }
    { const char * tb_v16650 = "            float v = io[11 + k] > 0 ? (io[11 + k] < 1 ? io[11 + k] : 1) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16650; }
