    { const char * tb_v16980 = "    static const int bmap[11] = { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_SELECT, TB_PB_START, TB_PB_HOME, TB_PB_L3, TB_PB_R3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16980; }
