    { const char * tb_v17065 = "    snprintf(buf, sizeof buf, \"set_cursor: нет курсора «%s»; есть arrow, hand, text, move, resize_x, resize_y, wait, none\", name);\n"; *(const char * *)tb_grow(v_lines) = tb_v17065; }
    { const char * tb_v17066 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v17066; }
    { const char * tb_v17067 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17067; }
    { const char * tb_v17068 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v17068; }
    { const char * tb_v17069 = "// в ядре без ОС своей libc нет: две маленькие замены для menu_add\n"; *(const char * *)tb_grow(v_lines) = tb_v17069; }
    { const char * tb_v17070 = "static const char *tb_strchr0(const char *s, int c) { for (; *s; s++) if (*s == (char)c) return s; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17070; }
    { const char * tb_v17071 = "static char *tb_strdup0(const char *s) { size_t n = strlen(s) + 1; char *d = malloc(n); if (d) memcpy(d, s, n); return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17071; }
    { const char * tb_v17072 = "#define strchr tb_strchr0\n"; *(const char * *)tb_grow(v_lines) = tb_v17072; }
    { const char * tb_v17073 = "#define strdup tb_strdup0\n"; *(const char * *)tb_grow(v_lines) = tb_v17073; }
    { const char * tb_v17074 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v17074; }
    { const char * tb_v17075 = "// меню системы (1.3): menu_add(\"Файл/Сохранить\", \"cmd+s\"), выбранный пункт — menu_pick()\n"; *(const char * *)tb_grow(v_lines) = tb_v17075; }
    { const char * tb_v17076 = "TB_API char *tb_menu_path[TB_MENU_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v17076; }
    { const char * tb_v17077 = "TB_API void tb_menu_add(const char *path, const char *keys, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17077; }
    { const char * tb_v17078 = "    if (!tb_px) tb_crash(line, \"menu_add: сначала открой окно (window_open)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17078; }
    { const char * tb_v17079 = "    const char *sl = strchr(path, '/');\n"; *(const char * *)tb_grow(v_lines) = tb_v17079; }
    { const char * tb_v17080 = "    if (!sl || sl == path || !sl[1]) tb_crash(line, \"menu_add: пункт пишется как \\\"Меню/Пункт\\\", например \\\"Файл/Сохранить\\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17080; }
    { const char * tb_v17081 = "    if (tb_menu_n >= TB_MENU_MAX) tb_crash(line, \"menu_add: больше 256 пунктов меню не бывает\");\n"; *(const char * *)tb_grow(v_lines) = tb_v17081; }
    { const char * tb_v17082 = "    size_t tl = (size_t)(sl - path);\n"; *(const char * *)tb_grow(v_lines) = tb_v17082; }
    { const char * tb_v17083 = "    char top[200], key[32] = \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v17083; }
    { const char * tb_v17084 = "    if (tl >= sizeof top) tl = sizeof top - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17084; }
    { const char * tb_v17085 = "    memcpy(top, path, tl); top[tl] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17085; }
    { const char * tb_v17086 = "    // клавиши: \"cmd+shift+s\" — cmd (Command на Mac, Ctrl на Windows), shift, alt, ctrl и одна клавиша в конце\n"; *(const char * *)tb_grow(v_lines) = tb_v17086; }
    { const char * tb_v17087 = "    int mods = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17087; }
    { const char * tb_v17088 = "    const char *p = keys;\n"; *(const char * *)tb_grow(v_lines) = tb_v17088; }
    { const char * tb_v17089 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17089; }
    { const char * tb_v17090 = "        const char *e = strchr(p, '+');\n"; *(const char * *)tb_grow(v_lines) = tb_v17090; }
    { const char * tb_v17091 = "        if (e == p) e = 0;   // сама клавиша «+»\n"; *(const char * *)tb_grow(v_lines) = tb_v17091; }
    { const char * tb_v17092 = "        size_t n = e ? (size_t)(e - p) : strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v17092; }
    { const char * tb_v17093 = "        if (n == 3 && strncmp(p, \"cmd\", 3) == 0) mods |= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17093; }
    { const char * tb_v17094 = "        else if (n == 5 && strncmp(p, \"shift\", 5) == 0) mods |= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17094; }
    { const char * tb_v17095 = "        else if (n == 3 && strncmp(p, \"alt\", 3) == 0) mods |= 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v17095; }
    { const char * tb_v17096 = "        else if (n == 4 && strncmp(p, \"ctrl\", 4) == 0) mods |= 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v17096; }
    { const char * tb_v17097 = "        else { if (n >= sizeof key) n = sizeof key - 1; memcpy(key, p, n); key[n] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17097; }
    { const char * tb_v17098 = "        if (!e) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v17098; }
    { const char * tb_v17099 = "        p = e + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17099; }
    { const char * tb_v17100 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17100; }
    { const char * tb_v17101 = "    if (key[0] && key[1]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17101; }
    { const char * tb_v17102 = "        char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v17102; }
    { const char * tb_v17103 = "        snprintf(buf, sizeof buf, \"menu_add: клавиша «%s» — нужна одна буква, цифра или знак, например \\\"cmd+s\\\"\", key);\n"; *(const char * *)tb_grow(v_lines) = tb_v17103; }
    { const char * tb_v17104 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v17104; }
    { const char * tb_v17105 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17105; }
    { const char * tb_v17106 = "    if (key[0] && !mods) mods = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17106; }
    { const char * tb_v17107 = "    int n = tb_menu_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v17107; }
    { const char * tb_v17108 = "    tb_menu_path[n] = strdup(path);\n"; *(const char * *)tb_grow(v_lines) = tb_v17108; }
    { const char * tb_v17109 = "    tb_gfx_menu_add(n, top, sl + 1, key, mods);\n"; *(const char * *)tb_grow(v_lines) = tb_v17109; }
    { const char * tb_v17110 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17110; }
    { const char * tb_v17111 = "TB_API const char *tb_menu_pick(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17111; }
    { const char * tb_v17112 = "    if (!tb_menu_hit) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v17112; }
    { const char * tb_v17113 = "    int i = tb_menu_hit - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17113; }
    { const char * tb_v17114 = "    tb_menu_hit = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17114; }
    { const char * tb_v17115 = "    size_t n = strlen(tb_menu_path[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v17115; }
    { const char * tb_v17116 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17116; }
    { const char * tb_v17117 = "    memcpy(s, tb_menu_path[i], n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17117; }
    { const char * tb_v17118 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v17118; }
    { const char * tb_v17119 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17119; }
    { const char * tb_v17120 = "TB_API int tb_menu_native(void) { return tb_gfx_menu_native(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v17120; }
    { const char * tb_v17121 = "// text_keys(): команды системы с прошлого раза через пробел (\"moveWordLeft: deleteBackward:\")\n"; *(const char * *)tb_grow(v_lines) = tb_v17121; }
    { const char * tb_v17122 = "TB_API const char *tb_text_keys(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17122; }
    { const char * tb_v17123 = "    char *s = tb_tmem(tb_ntkeys + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17123; }
    { const char * tb_v17124 = "    memcpy(s, tb_tkeys, tb_ntkeys);\n"; *(const char * *)tb_grow(v_lines) = tb_v17124; }
    { const char * tb_v17125 = "    s[tb_ntkeys] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17125; }
    { const char * tb_v17126 = "    tb_ntkeys = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17126; }
    { const char * tb_v17127 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v17127; }
    { const char * tb_v17128 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17128; }
    { const char * tb_v17129 = "TB_API int tb_text_keys_native(void) { return tb_tkeys_on; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17129; }
    { const char * tb_v17130 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v17130; }
    { const char * tb_v17131 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v17131; }
    { const char * tb_v17132 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v17132; }
    { const char * tb_v17133 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v17133; }
    { const char * tb_v17134 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v17134; }
    { const char * tb_v17135 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v17135; }
    { const char * tb_v17136 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v17136; }
    { const char * tb_v17137 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v17137; }
    { const char * tb_v17138 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v17138; }
    { const char * tb_v17139 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v17139; }
    { const char * tb_v17140 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v17140; }
    { const char * tb_v17141 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v17141; }
    { const char * tb_v17142 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v17142; }
    { const char * tb_v17143 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v17143; }
    { const char * tb_v17144 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v17144; }
    { const char * tb_v17145 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v17145; }
    { const char * tb_v17146 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v17146; }
    { const char * tb_v17147 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v17147; }
    { const char * tb_v17148 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v17148; }
    { const char * tb_v17149 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v17149; }
    { const char * tb_v17150 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v17150; }
    { const char * tb_v17151 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v17151; }
    { const char * tb_v17152 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v17152; }
    { const char * tb_v17153 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v17153; }
    { const char * tb_v17154 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v17154; }
    { const char * tb_v17155 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v17155; }
    { const char * tb_v17156 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v17156; }
    { const char * tb_v17157 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v17157; }
    { const char * tb_v17158 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v17158; }
    { const char * tb_v17159 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v17159; }
    { const char * tb_v17160 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v17160; }
    { const char * tb_v17161 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v17161; }
    { const char * tb_v17162 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v17162; }
    { const char * tb_v17163 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v17163; }
    { const char * tb_v17164 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v17164; }
    { const char * tb_v17165 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17165; }
    { const char * tb_v17166 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17166; }
    { const char * tb_v17167 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v17167; }
    { const char * tb_v17168 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v17168; }
    { const char * tb_v17169 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17169; }
    { const char * tb_v17170 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17170; }
    { const char * tb_v17171 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17171; }
    { const char * tb_v17172 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v17172; }
    { const char * tb_v17173 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v17173; }
    { const char * tb_v17174 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17174; }
    { const char * tb_v17175 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v17175; }
    { const char * tb_v17176 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17176; }
    { const char * tb_v17177 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v17177; }
    { const char * tb_v17178 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17178; }
    { const char * tb_v17179 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v17179; }
    { const char * tb_v17180 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v17180; }
    { const char * tb_v17181 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v17181; }
    { const char * tb_v17182 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v17182; }
    { const char * tb_v17183 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v17183; }
    { const char * tb_v17184 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v17184; }
    { const char * tb_v17185 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17185; }
    { const char * tb_v17186 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17186; }
    { const char * tb_v17187 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v17187; }
    { const char * tb_v17188 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v17188; }
    { const char * tb_v17189 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17189; }
    { const char * tb_v17190 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v17190; }
    { const char * tb_v17191 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17191; }
    { const char * tb_v17192 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17192; }
    { const char * tb_v17193 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v17193; }
    { const char * tb_v17194 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v17194; }
    { const char * tb_v17195 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v17195; }
    { const char * tb_v17196 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v17196; }
    { const char * tb_v17197 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17197; }
    { const char * tb_v17198 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v17198; }
    { const char * tb_v17199 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v17199; }
    { const char * tb_v17200 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17200; }
    { const char * tb_v17201 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17201; }
    { const char * tb_v17202 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v17202; }
